"use client";

import type { ComponentProps, CSSProperties } from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BADGE_SIZE, useBarSize } from "./barSize";

/**
 * src/components/badge.tsx — a plain, stock shadcn Badge. Not vendored
 * anywhere else in this repo (checked apps/docs and packages/inspector —
 * absent from both), so this is written fresh rather than ported; it's a
 * small, extremely standard shadcn primitive with nothing repo-specific to
 * preserve. No `asChild`/Slot support — this app has no reason yet to
 * render a Badge as a link, and skipping it avoids a new dependency.
 *
 * WHY `size` was added here (stock shadcn's Badge has none): the Bar size
 * cascade (barSize.tsx) needs somewhere to land on Badge, and there was no
 * existing scale to hook into. Four rungs, matching `Bar`'s own directly.
 *
 * WHY `shape` defaults to `"rounded"` rather than flipping to pill
 * (docs/FEEDBACK-2026-09-17b-PLAN.md A-1, Zach: "show some badges with a
 * more pill shape"): he asked to *see* the pill option, not replace the
 * landed look — every existing caller (in particular `Bar`'s title badge,
 * which reads as a chip on purpose) must render unchanged. `rounded-full`
 * is opt-in via `shape="pill"`, not the new floor.
 */
const badgeVariants = cva(
  "relative inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border font-medium whitespace-nowrap transition-[color,box-shadow] [&>svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground",
        secondary: "border-transparent bg-secondary text-secondary-foreground",
        destructive: "border-transparent bg-destructive text-white dark:bg-destructive/60",
        // docs/INVALID-STATES-PLAN.md §5's Badge row: "amber bg, dark
        // text" — one cva row, no new component. `--bbox-warning` (ported
        // in src/globals.css) stays light enough in BOTH themes that black
        // text keeps its contrast; `destructive` above needs the opposite
        // (white-on-dark-red) for the same reason.
        warning: "border-transparent bg-[var(--bbox-warning)] text-black",
        // The one variant with a REAL (non-transparent) border, so it's
        // the one that gets `--bbox-skin-line-override`: default/secondary/
        // destructive are already `border-transparent` and need nothing —
        // suppressing an already-invisible border would be a no-op. See
        // block.tsx's own line-override note on why the colour a skin
        // suppresses has to be the one the STATE cascade already owns.
        outline: "border-[color:var(--bbox-skin-line-override,currentColor)] text-foreground",
      },
      size: {
        sm: "gap-0.5 px-1.5 py-0 text-[0.65rem] [&>svg]:size-2.5",
        md: "gap-1 px-2 py-0.5 text-xs [&>svg]:size-3",
        lg: "gap-1 px-2.5 py-1 text-sm [&>svg]:size-3.5",
        xl: "gap-1.5 px-3 py-1 text-base [&>svg]:size-4",
      },
      // WHY radius moved OFF these two classes and onto inline style
      // (see the component body): `rounded-md`/`rounded-full` bake a
      // fixed radius no skin token can reach. The literal each falls back
      // to below is unchanged from before this port — `rounded-md` here
      // resolves to `var(--radius-md)` = 8px on this app's `--radius:
      // 0.625rem` base, captured live off `components-text-marks-badge--variants` before
      // the edit.
      shape: {
        rounded: "",
        pill: "",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
      shape: "rounded",
    },
  },
);

export interface BadgeProps extends ComponentProps<"span">, VariantProps<typeof badgeVariants> {}

export function Badge({ className, variant, size, shape, style, ...props }: BadgeProps) {
  // Explicit `size` wins; the ambient Bar cascade is only the fallback when
  // `size` itself is omitted, `"md"` (cva's own default) is the floor when
  // there is no Bar ancestor either.
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BADGE_SIZE[barSize]) ?? "md";
  const resolvedShape = shape ?? "rounded";
  return (
    <span
      data-slot="badge"
      data-size={resolvedSize}
      data-shape={resolvedShape}
      // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M7. The edge has
      // no props, so its default seed is geometry-derived
      // (`${width}x${height}`) — a different wobble PATTERN than this
      // component's own semantic seed, `badge:${resolvedSize}:${resolvedShape}`
      // (same character and amplitude either way, just a different jitter
      // sequence). Publishing it closes that gap: `sketchAtEdge.ts`'s
      // `seedForBox` reads this attribute first.
      data-bbox-seed={`badge:${resolvedSize}:${resolvedShape}`}
      className={cn(badgeVariants({ variant, size: resolvedSize, shape: resolvedShape }), className)}
      style={{
        borderRadius:
          resolvedShape === "pill"
            ? "var(--bbox-skin-radius-pill, 9999px)"
            : "var(--bbox-skin-radius, var(--radius-md))",
        // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M6.
        // `currentColor` IS this variant's resolved line colour — every
        // variant above sets its own `text-*` class, and a real CSS border
        // (the `outline` variant) is already drawn in `currentColor`. A
        // boundary twin is appended as a CHILD of this span, so it inherits
        // the same `color` and lands on the same value without this
        // component importing the skin or hardcoding a token.
        ...({ "--bbox-ink-state": "currentColor" } as CSSProperties),
        ...style,
      }}
      {...props}
    >
      {props.children}
    </span>
  );
}

export { badgeVariants };

import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";
import { BarSizeProvider } from "./barSize";

/**
 * Bar — a horizontal strip with three slots (left · center · right).
 * Structure is unchanged from the reset: no appearance cascade, no
 * tone/state, just the three slots. What changed in the shadcn/Tailwind
 * migration is HOW it's painted — Tailwind utilities against the shadcn CSS
 * variables in src/globals.css instead of raw `style={{...}}` colors,
 * borrowing the visual vocabulary (not the props) of
 * packages/bbox-ui/src/bar.tsx.
 *
 * WHY the grid template is COMPUTED, not a fixed `1fr auto 1fr` (Zach: "if
 * the center slot is empty or so, then things in the other slots should
 * just continue to expand width wise, and not truncate. Unless you
 * specifically set a width limit"): `1fr auto 1fr` forces the left/right
 * tracks to stay EQUAL width even when one of them (or center) is empty —
 * that symmetry is exactly what real centering needs, but it also means an
 * empty center/right still claims (and wastes) half the bar's width, and a
 * long `left` label truncates against that artificial half-width ceiling
 * with the other half sitting empty. Measured live: a previous lane's own
 * `AllSizes` cascade cluster had already been moved from `left` to `center`
 * and its swatch widened 420→520px specifically to dodge this — a symptom
 * fix, not a cause fix, and reverted below now that the cause is fixed.
 * `barGridTemplateColumns` (below) keeps `1fr auto 1fr`'s symmetric flanks
 * ONLY when `center` actually holds content (centering is structurally
 * impossible without equal flanks, filled or not); otherwise the unused
 * slot's track collapses to `0` and `left`'s own track becomes the single
 * `1fr` that absorbs everything center/right aren't using — so it only
 * truncates once the BAR ITSELF is out of room, never before. A caller that
 * wants a truncation limit narrower than "however wide the bar naturally
 * is" sets one explicitly by wrapping its own content in a `width`-bounded
 * box — see `Bar.stories.tsx`'s `Widths` gallery — rather than `Bar`
 * growing a new prop for it.
 *
 * WHY no `rounded-lg`/`border`/`bg-card` here: a Bar is a layout strip, not
 * a card — the same way `Flex` paints nothing of its own. Zach: "I don't
 * like how the bars have these borders. they should fill the block footer
 * and headers edge to edge... the only lines are the dividers." A Bar
 * filling `Block`'s header/footer must read as flush with it, not as a
 * pill floating inside it — `Block`'s own `border-b`/`border-t` supply the
 * only lines. A standalone Bar story that wants to show the strip's own
 * extent adds a wrapper (e.g. a dashed box) at the STORY level instead.
 *
 * WHY `size` is also published via `BarSizeProvider`: Zach's size-cascade
 * ask — a Bar's contents should size themselves off the Bar's own `size`
 * rather than each getting hand-tuned. See `barSize.tsx` for the mapping
 * from these four rungs onto each consumer's own scale.
 */
function barGridTemplateColumns(hasCenter: boolean, hasRight: boolean): string {
  if (hasCenter) return "1fr auto 1fr";
  if (hasRight) return "1fr 0 auto";
  return "1fr 0 0";
}

export const BAR_SIZES = ["sm", "md", "lg", "xl"] as const;
export type BarSize = (typeof BAR_SIZES)[number];

/** Bar height per rung, px. */
export const BAR_HEIGHT: Record<BarSize, number> = { sm: 28, md: 36, lg: 48, xl: 60 };

export interface BarProps {
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
  size?: BarSize;
  style?: CSSProperties;
}

// WHY `overflow-clip` + a 4px `overflow-clip-margin` instead of plain
// `overflow-hidden`: a focusable control flush against a cell's edge (a
// left-slot FoldingChevron, a right-slot Toggle/Button) paints its
// focus-visible ring OUTSIDE its own border box — `hidden` clips that ink
// the instant it crosses the cell boundary, which is the actual cause of
// the bug Zach reported ("chevron has a box cut off on its left") and,
// measured live, hits any focusable control sitting flush at a cell edge,
// not just the chevron. `overflow-clip-margin` is the CSS-spec-native fix:
// it only relaxes where PAINT (ink like a box-shadow ring or an outline) is
// allowed to bleed past the clip box, layout overflow — the thing this
// class exists to contain, e.g. EditableText's own `minWidth:0`/ellipsis
// truncation still clips flush at (edge + 4px). 4px covers both the
// shadcn ring-3 box-shadow (3px spread, 0 offset) and the browser's native
// default outline that a bare-button control like FoldingChevron falls
// back to. Only takes effect on `overflow: clip` (not `hidden`), which is
// otherwise behaviourally identical for this cell's purposes — no scroll
// either way.
const cellClass = "flex min-w-0 items-center overflow-clip [overflow-clip-margin:4px]";

export function Bar({ left, center, right, size = "md", style }: BarProps) {
  return (
    <BarSizeProvider size={size}>
      <div
        data-slot="bar"
        data-size={size}
        // WHY `group`: a plain Tailwind marker class, paints nothing on its
        // own — it exists so a `FoldingChevron reveal="hover"` inside this
        // Bar can key its `group-hover`/`group-focus-within` reveal off the
        // Bar itself ("the surrounding region... the Bar/header it lives
        // in", not the 24px button). Harmless for every Bar that has no
        // such child.
        className={cn("group grid w-full items-center gap-2 px-3 text-sm text-card-foreground")}
        style={{
          gridTemplateColumns: barGridTemplateColumns(center !== undefined, right !== undefined),
          height: BAR_HEIGHT[size],
          ...style,
        }}
      >
        <div data-slot="bar-left" className={cn(cellClass, "justify-start")}>
          {left}
        </div>
        <div data-slot="bar-center" className={cn(cellClass, "justify-center")}>
          {center}
        </div>
        <div data-slot="bar-right" className={cn(cellClass, "justify-end")}>
          {right}
        </div>
      </div>
    </BarSizeProvider>
  );
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

import type { BarSize } from "./bar";
import type { EditableTextSize } from "./editableText.layout";
import type { GlyphSize } from "./glyph.layout";

/**
 * src/components/barSize.tsx — the size CASCADE from `Bar` down to its own
 * contents. Zach: "various things inside of the bar will size themselves
 * correctly... with a 'large bar' vs small bar you don't need to hand tune
 * each element inside." A React context, mirroring `glyph.tsx`'s own
 * resolver-context pattern (provider + `use*` hook), not a new prop
 * threaded through every layer in between — `Bar` already owns a `size`
 * prop (bar.tsx); this only makes that value reach descendants.
 *
 * The mapping from Bar's four rungs (sm/md/lg/xl) onto each consumer's OWN
 * size scale lives HERE, in one place, rather than scattered per component.
 * `Glyph`/`EditableText` already share Bar's exact four-rung ladder, so
 * their mapping is the identity — still spelled out below so all five
 * mappings are visible in one lookup. `Badge`/`Button`/`Toggle` each carry
 * a differently-shaped scale of their own.
 *
 * An explicit size prop on any child ALWAYS wins — every consumer only
 * calls into this context as the fallback when its own prop is
 * `undefined`, same "explicit beats derived" rule `glyphFootprint` already
 * applies to its own size/sizePreset pair.
 */

const BarSizeContext = createContext<BarSize | undefined>(undefined);

/** Mounted by `Bar` itself (bar.tsx) — not meant to be reached for by callers. */
export function BarSizeProvider({ size, children }: { size: BarSize; children?: ReactNode }) {
  return <BarSizeContext.Provider value={size}>{children}</BarSizeContext.Provider>;
}

/** `undefined` outside any `Bar` — "not inside a cascade," not an error;
 *  same shape as `useGlyphResolver`'s "no provider mounted" case. */
export function useBarSize(): BarSize | undefined {
  return useContext(BarSizeContext);
}

/** Glyph's own ladder (glyph.layout.ts's `GLYPH_SIZES`) is identical to
 *  Bar's four rungs, so the cascade is the identity. */
export const BAR_SIZE_TO_GLYPH_PRESET: Record<BarSize, GlyphSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** EditableText's own ladder (editableText.layout.ts's `EDITABLE_TEXT_SIZES`)
 *  is the same four-rung ladder too — see that file's own comment on why
 *  Glyph/EditableText/Port each keep an independent ladder rather than
 *  sharing one, even though the VALUES line up. */
export const BAR_SIZE_TO_EDITABLE_TEXT_SIZE: Record<BarSize, EditableTextSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Badge has no size scale of its own yet (badge.tsx was a plain stock
 *  shadcn Badge, one size only) — this cascade is what gives it one,
 *  matching Bar's own four rungs directly. */
export type BadgeSize = "sm" | "md" | "lg" | "xl";
export const BAR_SIZE_TO_BADGE_SIZE: Record<BarSize, BadgeSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Button and Toggle each already ship a THREE-rung size scale
 *  (sm/default/lg — no "xl"), so Bar's `xl` clamps down to their largest
 *  rung rather than this cascade inventing a fourth one they don't have. */
export type ButtonToggleSize = "sm" | "default" | "lg";
export const BAR_SIZE_TO_BUTTON_SIZE: Record<BarSize, ButtonToggleSize> = {
  sm: "sm",
  md: "default",
  lg: "lg",
  xl: "lg",
};
export const BAR_SIZE_TO_TOGGLE_SIZE: Record<BarSize, ButtonToggleSize> = BAR_SIZE_TO_BUTTON_SIZE;

/*
 * CodeEditor — reconciled from packages/bbox-ui/src/codeField.css (current
 * on main: the box chrome, caret/selection/placeholder colours) and
 * claude/code-block-primitive's codeBlock.css (recovered: the opaque
 * gutter, the overflow/scroll variants, the tok-* syntax palette — all
 * deleted from main's codeField.css by 368a524's trim). Colours are stock
 * shadcn tokens (src/globals.css) — this app carries no bbox-* theme
 * tokens, so the `var(--bbox-accent, #4f6ee5)` shape below always falls
 * through to its literal, same pattern as editableText.tsx's
 * `var(--bbox-ring, currentColor)`.
 */

.bbox-code-editor {
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 4px 6px;
  /*
   * The skin seam (src/skin/skin.ts + skin.css), same pattern this file's
   * own `--bbox-tok-*` lines already use one level down: a token read at
   * the call site with TODAY'S value (1px solid var(--color-border), 6px)
   * as its own `var()` fallback, so a consumer who never imports skin.css
   * renders exactly the pixels this replaced.
   */
  border: var(--bbox-skin-stroke-width, 1px) solid var(--bbox-skin-stroke, var(--color-border));
  border-radius: var(--bbox-skin-radius, 6px);
  /* `--bbox-tok-bg`/`--bbox-tok-fg` (codeEditorTheme.ts) still take
     precedence — a syntax theme is a background + foreground pair, not
     just token colours, and a Dark Modern editor on a sketch-skinned
     page is still Dark Modern. Only once NEITHER a theme nor a skin sets
     one does it fall through to today's literal, unchanged. */
  background: var(--bbox-tok-bg, var(--bbox-skin-surface, var(--color-card)));
  color: var(--bbox-tok-fg, var(--bbox-skin-fg, var(--color-foreground)));
  cursor: text;
  overflow: hidden;
}

/*
 * NO `SketchOutline` here, unlike Block/Badge/Port — a deliberate scope
 * boundary, not an oversight: CodeMirror's `EditorView` mounts itself
 * imperatively into `.bbox-code-editor` via `hostRef` (codeEditor.tsx),
 * which is the sole child React ever manages on that node. A drawn
 * outline needs to be a SIBLING (so React and CodeMirror never fight over
 * the same parent's children), which means wrapping the whole component in
 * a new root div — real surgery on a component nothing else in this port
 * touches, for a cosmetic layer, not a token-correctness one. So in the
 * sketch skin CodeEditor's border/background genuinely vanish (same
 * `--bbox-skin-stroke: transparent` / `-surface: transparent` every other
 * skinned component obeys) with no hand-drawn replacement — the field
 * reads as bare text on the canvas, which is honest for "no box", just
 * not as demonstrative as Block/Badge/Port's drawn ring. Matches
 * packages/bbox-ui/src/codeField.css's own scope exactly (it wires only
 * `--bbox-skin-font-mono`, nothing else) — this port already goes further
 * by wiring border/radius/surface/fg too.
 */

.bbox-code-editor[aria-disabled="true"] {
  opacity: 0.6;
  cursor: default;
}

.bbox-code-editor:focus-within {
  border-color: var(--color-primary);
}

.bbox-code-editor .cm-editor {
  outline: none;
  background: transparent;
  height: auto;
}

.bbox-code-editor .cm-scroller {
  /* Ported from packages/bbox-ui/src/codeField.css:90 (its ONLY skin-token
     line) — a code editor stays monospace by default and the sketch skin
     is the one place that's a real taste call, not a bug: Zach, D3,
     "a code field inherits the skin rather than pinning monospace." */
  font-family: var(--bbox-skin-font-mono, ui-monospace, "SF Mono", Menlo, Consolas, monospace);
  /* Inherits the box's own inline `fontSize` (`fontSizePx`) rather than
     hardcoding a copy — the only way a per-instance size reaches
     CodeMirror's internal DOM. */
  font-size: inherit;
  line-height: 1.4;
}

/*
 * `overflow` (codeEditor.tsx): what a line wider than the box does.
 * `clip` — an <input>-like port label: cut at the edge, no bar. `scroll` —
 * a real horizontal scrollbar once content is wider than the box (the IDE
 * feel of Zach's screenshot). `wrap` — CodeMirror's own `lineWrapping`
 * folds the line, so the scroller only ever needs to grow vertically.
 */
.bbox-code-editor[data-overflow="clip"] .cm-scroller {
  overflow: hidden;
}

.bbox-code-editor[data-overflow="scroll"] .cm-scroller,
.bbox-code-editor[data-overflow="wrap"] .cm-scroller {
  overflow: auto;
}

.bbox-code-editor .cm-content {
  padding: 0;
  caret-color: var(--color-primary);
}

/*
 * No `white-space` set on `.cm-content` above, on purpose — measured live (headless Chrome):
 * CodeMirror's OWN base theme already puts `white-space: pre` on
 * `.cm-content` at the SAME specificity as a plain `.bbox-code-editor
 * .cm-content` rule would be (two classes each), and CodeMirror's
 * stylesheet is injected at `EditorView` construction time, i.e. AFTER this
 * file's import — so it wins the cascade tie regardless of what this rule
 * declared. codeBlock.css's own `white-space: nowrap` here had the exact
 * same dead-on-arrival shape (confirmed: the recovered branch never beat
 * this tie either). It doesn't matter: `pre` already gives "no soft wrap"
 * (CodeMirror still renders one `.cm-line` per line regardless of this
 * property), and unlike `nowrap` it does NOT collapse a run of leading
 * spaces — which Python's indentation needs. Fighting the cascade for
 * `nowrap` here would have made indentation render wrong the moment it won.
 */

/* WHY this rule exists at all: CodeMirror's `lineWrapping` sets
   `white-space: pre-wrap` through its own `.ͼ1 .cm-lineWrapping` rule —
   specificity (0,2,0), the SAME as `.cm-content` alone, so which wins would
   otherwise depend on stylesheet order. Three classes settles it. */
.bbox-code-editor .cm-content.cm-lineWrapping {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.bbox-code-editor .cm-line {
  padding: 0;
}

/* The line-number gutter (`lineNumbers`): a hairline on its right, numbers
   in the faint ink, room for a few digits before the content's own padding.
   WHY it needs a REAL (opaque) background, not `transparent`: CodeMirror
   pins the gutter with its own `position: sticky; left: 0` so it stays put
   while `.cm-content`'s lines scroll underneath it horizontally
   (`data-overflow="scroll"`/`"wrap"` above). A transparent gutter lets that
   scrolled text show through behind the numbers as it passes — matching the
   editor's own surface colour, not the page's, keeps it opaque without
   drawing a visibly different panel. This is the fix codeBlock.css shipped
   and main's codeField.css trim lost along with the gutter entirely. */
.bbox-code-editor .cm-gutters {
  background: var(--color-card);
  color: var(--color-muted-foreground);
  border-right: 1px solid var(--color-border);
  min-width: 36px;
  justify-content: flex-end;
  margin-right: 12px;
}

.bbox-code-editor .cm-lineNumbers .cm-gutterElement {
  padding: 0 8px 0 6px;
}

.bbox-code-editor .cm-focused .cm-activeLine,
.bbox-code-editor .cm-focused .cm-activeLineGutter {
  background: color-mix(in srgb, var(--color-primary) 7%, transparent);
}

.bbox-code-editor .cm-placeholder {
  color: var(--color-muted-foreground);
  font-style: normal;
}

.bbox-code-editor .cm-selectionBackground,
.bbox-code-editor .cm-focused .cm-selectionBackground,
.bbox-code-editor ::selection {
  background: color-mix(in srgb, var(--color-primary) 30%, transparent);
}

.bbox-code-editor .cm-cursor {
  border-left-color: var(--color-primary);
}

/*
 * The syntax palette. `classHighlighter` (@lezer/highlight) emits stable
 * `tok-*` classes with no colour of its own; this is the one place they get
 * one, ported from codeBlock.css's `bbox-code-tokens` block.
 *
 * WHY every selector carries BOTH root classes (0,3,0): CodeMirror's own
 * fallback highlight style, when a host happens to mount it, paints tokens
 * through generated `.ͼN .ͼM` rules at (0,2,0) — a bare
 * `.bbox-code-tokens .tok-keyword` would tie on specificity and lose or win
 * by stylesheet order. Three classes settles it in this sheet's favour.
 *
 * WHY each rule now reads `var(--bbox-tok-*, <today's literal>)`
 * (docs/FEEDBACK-2026-09-17b-PLAN.md A-2, codeEditorTheme.ts): a VS Code
 * syntax theme is a PALETTE SWAP over this exact selector set, not a
 * second highlighter or a per-theme CodeMirror `EditorView.theme()` — see
 * codeEditor.tsx:297's own WHY. `codeEditorThemeVars()` sets the
 * `--bbox-tok-*` custom properties inline on the root; with none set (the
 * default, and any unrecognised theme id) every rule falls straight
 * through to the literal it had before this change, byte-identical.
 */
.bbox-code-editor.bbox-code-tokens .tok-keyword,
.bbox-code-editor.bbox-code-tokens .tok-operatorKeyword,
.bbox-code-editor.bbox-code-tokens .tok-definitionKeyword,
.bbox-code-editor.bbox-code-tokens .tok-moduleKeyword {
  color: var(--bbox-tok-keyword, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 78%, var(--color-foreground)));
  font-weight: 600;
}

/* Split from the group above so a theme's "control keyword" row
   (if/for/return/…) has somewhere to land — see codeEditorTheme.ts's own
   WHY on why `classHighlighter` never actually emits this class today. */
.bbox-code-editor.bbox-code-tokens .tok-controlKeyword {
  color: var(--bbox-tok-control-keyword, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 78%, var(--color-foreground)));
  font-weight: 600;
}

.bbox-code-editor.bbox-code-tokens .tok-string,
.bbox-code-editor.bbox-code-tokens .tok-docString,
.bbox-code-editor.bbox-code-tokens .tok-character,
.bbox-code-editor.bbox-code-tokens .tok-attributeValue {
  color: var(--bbox-tok-string, color-mix(in srgb, var(--bbox-success, #2f9e5a) 62%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-number,
.bbox-code-editor.bbox-code-tokens .tok-integer,
.bbox-code-editor.bbox-code-tokens .tok-float,
.bbox-code-editor.bbox-code-tokens .tok-bool,
.bbox-code-editor.bbox-code-tokens .tok-atom,
.bbox-code-editor.bbox-code-tokens .tok-null,
.bbox-code-editor.bbox-code-tokens .tok-unit {
  color: var(--bbox-tok-number, color-mix(in srgb, var(--bbox-warning, #c98a1b) 58%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-comment,
.bbox-code-editor.bbox-code-tokens .tok-lineComment,
.bbox-code-editor.bbox-code-tokens .tok-blockComment,
.bbox-code-editor.bbox-code-tokens .tok-meta {
  color: var(--bbox-tok-comment, var(--color-muted-foreground));
  font-style: italic;
}

.bbox-code-editor.bbox-code-tokens .tok-typeName,
.bbox-code-editor.bbox-code-tokens .tok-className,
.bbox-code-editor.bbox-code-tokens .tok-namespace {
  color: var(--bbox-tok-type, color-mix(in srgb, var(--bbox-accent, #4f6ee5) 55%, var(--color-foreground)));
}

.bbox-code-editor.bbox-code-tokens .tok-variableName,
.bbox-code-editor.bbox-code-tokens .tok-variableName2,
.bbox-code-editor.bbox-code-tokens .tok-definition,
.bbox-code-editor.bbox-code-tokens .tok-self {
  color: var(--bbox-tok-variable, var(--bbox-accent, #4f6ee5));
}

.bbox-code-editor.bbox-code-tokens .tok-propertyName,
.bbox-code-editor.bbox-code-tokens .tok-attributeName,
.bbox-code-editor.bbox-code-tokens .tok-labelName {
  color: color-mix(in srgb, var(--bbox-danger, #c94b3f) 42%, var(--color-foreground));
}

/* WHY the fallback reads `var(--bbox-accent, #4f6ee5))` (the tok-variableName
   rule's own default above) and not `var(--color-foreground)`: this
   selector was dead until codeEditorHighlight.ts (its own WHY) started
   actually emitting `tok-function` — nothing ever exercised this rule's
   own literal, so it was never noticed that it disagreed with what a
   function name actually rendered as (`.tok-variableName`'s colour, since
   `.tok-function`/`.tok-definition`/`.tok-variableName` are now emitted
   together on the SAME element — see that file's own WHY on unioning
   classes). Every theme sets `--bbox-tok-function` explicitly, so this
   fallback only matters with no theme selected, and it has to match
   tok-variableName's fallback exactly or turning the class "on" silently
   recolours every function name (and call site) the moment no theme is
   set — a real regression, not a fidelity gain. */
.bbox-code-editor.bbox-code-tokens .tok-function,
.bbox-code-editor.bbox-code-tokens .tok-macroName {
  color: var(--bbox-tok-function, var(--bbox-accent, #4f6ee5));
  font-weight: 600;
}

.bbox-code-editor.bbox-code-tokens .tok-operator,
.bbox-code-editor.bbox-code-tokens .tok-punctuation,
.bbox-code-editor.bbox-code-tokens .tok-separator,
.bbox-code-editor.bbox-code-tokens .tok-bracket {
  color: var(--bbox-tok-operator, var(--color-muted-foreground));
}

.bbox-code-editor.bbox-code-tokens .tok-invalid {
  color: var(--bbox-danger, #c94b3f);
}

/*
 * The diagnostic axis's squiggle (docs/INVALID-STATES-PLAN.md §5's
 * CodeEditor row, §7's stock-parts table). `@codemirror/lint`'s OWN
 * baseTheme already paints `.cm-lintRange-*` with a `background-image`
 * data-URI squiggle baked from a LITERAL hex at import time (`#f11`,
 * `orange`, `#999`) — no CSS variable can reach inside an already-encoded
 * SVG string, so retinting means replacing the whole declaration, not
 * overriding one property. This kit already draws its OTHER resting-text
 * marks (EditableText, LabeledPort) as a plain `text-decoration: underline
 * wavy/dotted` — reusing that recipe here, instead of hand-building a
 * second SVG squiggle, is one fewer visual language for the same mark.
 *
 * WHY three classes (0,3,0): identical tie-break to `.cm-content.
 * cm-lineWrapping` a few rules up in this file — CodeMirror injects its
 * own `.ͼN.cm-lintRange-error` rule at (0,2,0) when the `EditorView`
 * mounts, AFTER this stylesheet loads, so stylesheet order alone would
 * let it win a same-specificity tie. `info` reuses the wavy/dotted split
 * `diagnosticUnderlineStyle` already draws elsewhere in this kit — dotted,
 * not wavy, so a merely-informational range never LOOKS as urgent as an
 * error or warning range beside it.
 */
.bbox-code-editor.bbox-code-tokens .cm-lintRange-error,
.bbox-code-editor.bbox-code-tokens .cm-lintRange-warning,
.bbox-code-editor.bbox-code-tokens .cm-lintRange-info {
  background-image: none;
  text-decoration-line: underline;
  text-decoration-thickness: 1.5px;
  text-underline-offset: 2px;
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-error,
.bbox-code-editor.bbox-code-tokens .cm-lintRange-warning {
  text-decoration-style: wavy;
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-info {
  text-decoration-style: dotted;
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-error {
  text-decoration-color: var(--bbox-danger, #c94b3f);
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-warning {
  text-decoration-color: var(--bbox-warning, #c98a1b);
}
.bbox-code-editor.bbox-code-tokens .cm-lintRange-info {
  text-decoration-color: var(--bbox-accent, #4f6ee5);
}

"use client";

// src/components/codeEditor.tsx — ported by value from packages/bbox-ui's
// CodeMirror field, reconciling two lineages that diverged on main:
//
// - packages/bbox-ui/src/codeField.tsx (592 lines, current on main) is the
//   engine this keeps almost verbatim: the write policy (`onWrite` per
//   keystroke via `codeEditorGesture.ts`'s `FieldGesture`), the single-line
//   guard, the Enter/Escape exit contract, the external-value-sync effect,
//   the wheel/pointerdown host-interop effects.
// - packages/bbox-ui/src/codeBlock.tsx (900 lines, deleted on main by
//   368a524 "CodeBlock becomes CodeField", recovered from
//   claude/code-block-primitive) is where `lineNumbers`, the `columns` →
//   pixel width maths (now `codeEditorLayout.ts`), and the `overflow`
//   clip/wrap/scroll modes came from — main's rename trimmed all three
//   along with the `grammar`/`mode`/rows machinery.
//
// Dropped entirely, on both sides: `grammar` (slot decorations +
// completion — `codeGrammar.ts`/`completionMenu.ts`), the rendered/source
// `mode` toggle and `CodeEditorRows` (`codeFieldRows.tsx`/`codeBlockRows`),
// `flatten`/`codeBlockUnits.ts`'s Python-unit folding, and the `look`
// preset ladder (`codeBlock.presets.ts`) — this app has no FieldSpec /
// appearance-cascade machinery to hang any of that on (see CLAUDE.md).
// `language` survives as its own prop (a raw CodeMirror `LanguageSupport`)
// specifically BECAUSE dropping `grammar` wholesale would also have
// dropped syntax highlighting, which the PseudoCode story plainly needs.
//
// `tooltipParent`/the completion popup's `tooltips()` extension are also
// dropped — nothing here ever opens a tooltip without `grammar`'s
// completion source, so parenting one was dead plumbing.

import {
  copyLineDown,
  copyLineUp,
  defaultKeymap,
  history,
  historyKeymap,
  moveLineDown,
  moveLineUp,
} from "@codemirror/commands";
import { syntaxHighlighting, type LanguageSupport } from "@codemirror/language";
import { linter as cmLinter, setDiagnostics as cmSetDiagnostics, type Diagnostic as CMDiagnostic } from "@codemirror/lint";
import {
  Compartment,
  EditorState,
  Prec,
  type Extension,
} from "@codemirror/state";
import {
  EditorView,
  keymap,
  lineNumbers as lineNumbersExtension,
  placeholder as placeholderExtension,
} from "@codemirror/view";
import {
  forwardRef,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  type CSSProperties,
} from "react";

import "./codeEditor.css";

import { FieldGesture } from "./codeEditorGesture";
import { externalSync, singleLineGuard } from "./codeEditorGuards";
import { codeEditorHighlightStyle } from "./codeEditorHighlight";
import { codeEditorWidthPx } from "./codeEditorLayout";
import { codeEditorThemeVars, type CodeEditorTheme } from "./codeEditorTheme";
import type { DiagnosticSeverity } from "./highlighter";

/** The horizontal padding baked into `.bbox-code-editor` in codeEditor.css —
 * kept as a constant here too so `columns`'s pixel maths (codeEditorLayout.ts)
 * matches what actually renders, rather than guessing the stylesheet's number. */
const PADDING_X = 6;

/** What a line wider than the box does. `clip` (the default — an <input>-like
 * port label: cut at the edge, no bar) and `scroll` (a horizontal scrollbar,
 * CodeMirror's own scroller — the IDE feel Zach's screenshot wants) both keep
 * `columns`' fixed width; `wrap` folds the line onto new rows instead and
 * ignores `columns` for width purposes since the text no longer runs past it. */
export type CodeEditorOverflow = "clip" | "wrap" | "scroll";

/**
 * One diagnostic-marked RANGE (docs/INVALID-STATES-PLAN.md §5's CodeEditor
 * row). This is the one mark-bearing shape in this axis that stays
 * POSITIONAL rather than the shared `Diagnostic` list every other
 * component takes: several squiggles at different character offsets in
 * one field are not competing judgements about a single element, so there
 * is nothing to rank down to a `max(severity)` — every range paints its
 * own severity, independently.
 */
export interface CodeEditorDiagnostic {
  from: number;
  to: number;
  severity: DiagnosticSeverity;
  message?: string;
}

export interface CodeEditorProps {
  /** The document. The field follows it whenever nobody is editing. */
  value: string;
  /** Write, per keystroke — the field's one write policy (see `codeEditorGesture.ts`). */
  onWrite(value: string): void;
  /** Open one undo step so an edit is one Ctrl+Z, not one per character. */
  beginEdit?(): void;
  /** The commit boundary — one call per gesture, however the field was left. */
  onEditEnd?(value: string, startValue: string): void;
  /** The syntax parser, e.g. `python()`/`javascript()`/`json()`. Omit for plain text. */
  language?: LanguageSupport;
  /**
   * A VS Code syntax palette (codeEditorTheme.ts) — an id resolved against
   * `CODE_EDITOR_THEMES`, or a `CodeEditorTheme` object directly. Applied
   * as CSS custom properties on the root, UNDER any caller `style` (a
   * caller override still wins). Omit, or pass an id that doesn't match
   * any known theme, for the ambient default palette — never blanks the
   * editor.
   */
  theme?: CodeEditorTheme | string;
  /**
   * A lane/document: several lines, Enter inserts a line, Alt+↑/↓ move one,
   * Shift+Alt+↓ copies one (CodeMirror's default keymap); Ctrl/Cmd+Enter is
   * the exit that Enter is for a single line. `false` (the default): one
   * line — a typed or pasted newline is dropped rather than growing the box.
   */
  multiline?: boolean;
  /** The line-number gutter. Off by default (a bare port-label line has nothing to number). */
  lineNumbers?: boolean;
  /** What a line wider than the box does. Defaults to `"clip"`. */
  overflow?: CodeEditorOverflow;
  /**
   * Characters across. `> 0` fixes the box's width to that many mono cells
   * plus padding (and the gutter when `lineNumbers` is on) — see
   * `codeEditorLayout.ts`'s `codeEditorWidthPx`. `0` (the default) fills
   * whatever the host gives. Ignored when `overflow === "wrap"` — a
   * wrapped line has no fixed width to overflow.
   */
  columns?: number;
  /** The type size, in px — also what `columns`'s pixel maths is computed against. */
  fontSizePx?: number;
  /** Pin every line to this height so lines can sit on a host's own rows. */
  lineHeightPx?: number;
  align?: "left" | "right";
  disabled?: boolean;
  placeholder?: string;
  ariaLabel?: string;
  ariaDescribedBy?: string;
  /** Forced `true` when any `diagnostics` range is `severity: "error"` —
   *  a whole-field error still sets this existing attribute (§5's own
   *  words); an explicit `true` here is never downgraded by an absent
   *  error range. */
  ariaInvalid?: boolean;
  /**
   * The diagnostic axis's positional shape — see `CodeEditorDiagnostic`'s
   * own doc. Painted with the stock `@codemirror/lint` squiggle
   * (`setDiagnostics`/`linter`, §5's own choice), retinted to this kit's
   * three severity tokens in codeEditor.css rather than CodeMirror's
   * hardcoded reds/oranges. No gutter, no Problems panel — §8 stops this
   * kit at the component-scale mark.
   */
  diagnostics?: CodeEditorDiagnostic[];
  className?: string;
  testId?: string;
  style?: CSSProperties;
  /** Take focus on mount; `'select'` also selects the whole line/document. */
  autoFocus?: boolean | "select";
  /** With `autoFocus`, put the caret here instead of selecting everything. */
  cursorAt?: number;
  /** With `autoFocus`, select exactly this range. */
  selectRange?: { from: number; to: number };
  /**
   * Enter (single-line) / Ctrl+Enter (multi) and Escape both end the
   * gesture by leaving the field (the value is never discarded — Ctrl+Z is
   * the retract). A host that owns its own editing session supplies its
   * own exits instead of the default `leave`.
   */
  onEnter?(): void;
  onEscape?(): void;
  /**
   * A host's own key handling, consulted BEFORE every keymap in this file
   * (`Prec.highest`, above even the Enter/Escape exits). Return `true` to
   * claim the key — it is then prevented and stopped; `false` lets it reach
   * CodeMirror untouched. The seam `keyboardReorder.ts`'s move-this-item
   * chord rides: it has to win over the default keymap's Ctrl+←/→ word-jump
   * on a row, and it must lose to nothing it did not ask for.
   */
  onKeyDown?(event: KeyboardEvent, view: EditorView): boolean;
  onViewReady?(view: EditorView): void;
}

export interface CodeEditorHandle {
  setCaret(offset: number): void;
  focus(): void;
}

/**
 * `CodeEditor` — the code text box: one line (the shape `LabeledPort`'s
 * label needs) or a multi-line lane/document (the shape the multiline port
 * editor needs), the same engine wearing different props. A real CodeMirror
 * document, so highlighting, IME, undo and the caret all come from one
 * mature engine rather than a mirror-div.
 *
 * WHY `CodeEditor` and not `CodeField`/`CodeBlock` (Zach, 2026-09-16: "its
 * clear that refers to the component, CodeMirror is the library"): `Code`
 * alone collides with nothing here, `Field`/`Block` each already carry a
 * different meaning elsewhere in bbox-ui (`Block` is the canvas node this
 * app also ships; `CodeBlock` collides with a real Code node on the
 * SystemSketch canvas) — `Editor` says what it is without borrowing either.
 */
export const CodeEditor = forwardRef<CodeEditorHandle, CodeEditorProps>(function CodeEditor({
  value,
  onWrite,
  beginEdit,
  onEditEnd,
  language,
  theme,
  multiline = false,
  lineNumbers = false,
  overflow = "clip",
  columns = 0,
  fontSizePx = 13,
  lineHeightPx,
  align = "left",
  disabled = false,
  placeholder,
  ariaLabel,
  ariaDescribedBy,
  ariaInvalid,
  diagnostics,
  className,
  testId,
  style,
  autoFocus = false,
  cursorAt,
  selectRange,
  onEnter,
  onEscape,
  onKeyDown,
  onViewReady,
}, ref) {
  const wrap = overflow === "wrap";
  const hostRef = useRef<HTMLDivElement>(null);
  const viewRef = useRef<EditorView | null>(null);
  const languageCompartment = useRef(new Compartment());
  const gutterCompartment = useRef(new Compartment());
  const editableCompartment = useRef(new Compartment());
  const placeholderCompartment = useRef(new Compartment());
  const metricsCompartment = useRef(new Compartment());

  const latest = useRef({
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    onKeyDown,
    value,
    disabled,
    multiline,
  });
  latest.current = {
    onWrite,
    beginEdit,
    onEditEnd,
    onEnter,
    onEscape,
    onKeyDown,
    value,
    disabled,
    multiline,
  };

  const metrics = (): Extension => [
    EditorView.theme({
      ...(lineHeightPx
        ? { ".cm-line": { lineHeight: `${lineHeightPx}px`, height: `${lineHeightPx}px` } }
        : {}),
      ...(align === "right" ? { ".cm-content": { textAlign: "right" } } : {}),
    }),
    ...(wrap ? [EditorView.lineWrapping] : []),
  ];

  const gestureRef = useRef<FieldGesture | null>(null);
  if (!gestureRef.current) {
    gestureRef.current = new FieldGesture(
      {
        write: (next) => latest.current.onWrite(next),
        begin: () => latest.current.beginEdit?.(),
        end: (next, start) => latest.current.onEditEnd?.(next, start),
      },
      "live",
    );
  }
  const gesture = gestureRef.current;

  const leave = (view: EditorView) => {
    view.contentDOM.blur();
    gesture.commit();
  };

  useImperativeHandle(ref, () => ({
    setCaret: (offset) => {
      const view = viewRef.current;
      if (!view) return;
      const anchor = Math.max(0, Math.min(offset, view.state.doc.length));
      view.dispatch({ selection: { anchor }, effects: EditorView.scrollIntoView(anchor) });
      view.focus();
    },
    focus: () => viewRef.current?.focus(),
  }), []);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const view = new EditorView({
      state: EditorState.create({
        doc: value,
        extensions: [
          history(),
          Prec.highest(
            EditorView.domEventHandlers({
              keydown: (event, target) => {
                if (event.isComposing || !latest.current.onKeyDown) return false;
                if (!latest.current.onKeyDown(event, target)) return false;
                event.preventDefault();
                event.stopPropagation();
                return true;
              },
            }),
          ),
          // Enter and Escape are the field's exits, handled on the raw
          // event so the keystroke can be STOPPED — see codeField.tsx's own
          // WHY (unchanged here; there is no completion popup any more to
          // give first refusal to, so that branch is simply gone).
          Prec.high(
            EditorView.domEventHandlers({
              keydown: (event, target) => {
                if (event.isComposing) return false;
                if (event.key !== "Enter" && event.key !== "Escape") return false;
                const modifierEnter = event.key === "Enter" && (event.ctrlKey || event.metaKey);
                if (event.key === "Enter" && latest.current.multiline && !modifierEnter) {
                  return false;
                }
                event.preventDefault();
                event.stopPropagation();
                const exit = event.key === "Enter" ? latest.current.onEnter : latest.current.onEscape;
                if (exit) exit();
                else leave(target);
                return true;
              },
            }),
          ),
          singleLineGuard(() => latest.current.multiline),
          keymap.of([
            { key: "Ctrl-ArrowUp", run: moveLineUp },
            { key: "Ctrl-ArrowDown", run: moveLineDown },
            { key: "Ctrl-Shift-ArrowUp", run: copyLineUp },
            { key: "Ctrl-Shift-ArrowDown", run: copyLineDown },
            ...defaultKeymap,
            ...historyKeymap,
          ]),
          languageCompartment.current.of(language ?? []),
          // WHY `codeEditorHighlightStyle` and not the stock `classHighlighter`
          // this used to mount directly: see codeEditorHighlight.ts's own WHY.
          syntaxHighlighting(codeEditorHighlightStyle),
          // WHY `null`, not a no-op `() => []` (measured, not assumed —
          // see this lane's own report for the timeline): `linter()`'s
          // ViewPlugin schedules `source(view)` to run ONCE, UNCONDITIONALLY,
          // `delay`ms (default 750) after every mount/relevant update —
          // it is not "only on a real edit". A `() => []` source WOULD
          // run at that mark and dispatch `setDiagnostics(state, [])`,
          // silently ERASING whatever this file's own sync effect (below)
          // had written — reproduced live: a squiggle painted at t=0
          // vanished at exactly t=750ms in every run. `null` is filtered
          // out of the `sources` facet entirely (lintConfig's own
          // `combine`), so the plugin's scheduled `run()` finds
          // `sources.length === 0` and dispatches NOTHING — this
          // component's diagnostics are pushed in from OUTSIDE (a host/
          // producer), never computed by a live in-editor linter, so
          // there must be no active source at all. The state field and
          // decorations (`lintState`/`lintExtensions`) still mount
          // unconditionally either way, which is all `setDiagnostics`
          // (the sync effect below) needs to have somewhere to write.
          cmLinter(null),
          gutterCompartment.current.of(lineNumbers ? [lineNumbersExtension()] : []),
          editableCompartment.current.of(EditorView.editable.of(!disabled)),
          placeholderCompartment.current.of(placeholder ? placeholderExtension(placeholder) : []),
          metricsCompartment.current.of(metrics()),
          EditorView.inputHandler.of((target, from, to, insertedText) => {
            if (latest.current.multiline || !/[\r\n]/.test(insertedText)) return false;
            const cleaned = insertedText.replace(/[\r\n]+/g, "");
            target.dispatch({
              changes: { from, to, insert: cleaned },
              selection: { anchor: from + cleaned.length },
            });
            return true;
          }),
          EditorView.updateListener.of((update) => {
            if (!update.docChanged) return;
            if (update.transactions.every((tr) => tr.annotation(externalSync))) return;
            const text = update.state.doc.toString();
            gesture.focus(latest.current.value);
            gesture.change(text);
          }),
          EditorView.domEventHandlers({
            focus: () => {
              if (latest.current.disabled) return;
              gesture.focus(latest.current.value);
            },
            blur: () => {
              globalThis.setTimeout(() => {
                const current = viewRef.current;
                if (current && !current.hasFocus) gesture.commit();
              }, 0);
            },
          }),
        ],
      }),
      parent: host,
    });
    viewRef.current = view;
    onViewReady?.(view);
    let frame = 0;
    if (autoFocus) {
      const take = () => {
        if (view.hasFocus || !viewRef.current) return;
        view.focus();
        const length = view.state.doc.length;
        if (selectRange) {
          const anchor = Math.max(0, Math.min(selectRange.from, length));
          const head = Math.max(anchor, Math.min(selectRange.to, length));
          view.dispatch({ selection: { anchor, head } });
        } else if (cursorAt !== undefined) {
          const anchor = Math.max(0, Math.min(cursorAt, length));
          view.dispatch({ selection: { anchor } });
        } else if (autoFocus === "select") {
          view.dispatch({ selection: { anchor: 0, head: view.state.doc.length } });
        }
      };
      take();
      frame = requestAnimationFrame(take);
    }
    return () => {
      cancelAnimationFrame(frame);
      viewRef.current = null;
      view.destroy();
    };
    // One mount for the field's lifetime; content, language, chrome and
    // editability flow through compartments and dispatches so a re-render
    // never tears the document down mid-gesture.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // The document follows the store whenever nobody is typing in it.
  useLayoutEffect(() => {
    const view = viewRef.current;
    if (!view || view.state.doc.toString() === value) return;
    if (gesture.isEditing && view.hasFocus) return;
    view.dispatch({
      changes: { from: 0, to: view.state.doc.length, insert: value },
      annotations: externalSync.of(true),
    });
  }, [value, gesture]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({ effects: languageCompartment.current.reconfigure(language ?? []) });
  }, [language]);

  // `setDiagnostics` REPLACES the lint state field wholesale — a plain
  // `Diagnostic[]`, not a compartment reconfigure, because it is data, not
  // an extension. `message` is required by `@codemirror/lint`'s own type
  // (ours is optional, §1's `Diagnostic.message` doc) — falling back to
  // the severity word keeps the squiggle's built-in hover from rendering
  // an empty popup when a producer marks a range before its prose exists.
  useLayoutEffect(() => {
    const view = viewRef.current;
    if (!view) return;
    const mapped: CMDiagnostic[] = (diagnostics ?? []).map((d) => ({
      from: d.from,
      to: d.to,
      severity: d.severity,
      message: d.message ?? d.severity,
    }));
    view.dispatch(cmSetDiagnostics(view.state, mapped));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [diagnostics]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: gutterCompartment.current.reconfigure(lineNumbers ? [lineNumbersExtension()] : []),
    });
  }, [lineNumbers]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: editableCompartment.current.reconfigure(EditorView.editable.of(!disabled)),
    });
  }, [disabled]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({ effects: metricsCompartment.current.reconfigure(metrics()) });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lineHeightPx, align, wrap]);

  useLayoutEffect(() => {
    viewRef.current?.dispatch({
      effects: placeholderCompartment.current.reconfigure(
        placeholder ? placeholderExtension(placeholder) : [],
      ),
    });
  }, [placeholder]);

  // See codeField.tsx's own WHY: a canvas host typically swallows the
  // native pointerdown/wheel a plain blur/scroll would rely on.
  useLayoutEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      const host = hostRef.current;
      const view = viewRef.current;
      if (!host || !view || !view.hasFocus) return;
      if (event.target instanceof Node && host.contains(event.target)) return;
      leave(view);
    };
    document.addEventListener("pointerdown", handlePointerDown, true);
    return () => document.removeEventListener("pointerdown", handlePointerDown, true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const handleWheel = (event: WheelEvent) => {
      if (viewRef.current?.hasFocus) event.stopPropagation();
    };
    host.addEventListener("wheel", handleWheel, { passive: false });
    return () => host.removeEventListener("wheel", handleWheel);
  }, []);

  /**
   * The gesture's third boundary: the host tore the field down while it was
   * still being edited. `codeEditorGesture.ts`'s own doc explains why this
   * cannot be left to `blur` — no `blur` fires for a focused element removed
   * from the DOM, so a commit-on-blur field silently loses the last edit.
   *
   * DEFERRED BY A FRAME, AND CANCELLED IF THE EFFECT COMES BACK — which is a
   * fix for a real, reproducible bug, not defensive noise.
   *
   * React StrictMode (development) mounts every effect, cleans it up, and
   * mounts it again. The element is never removed from the document; only the
   * effects are replayed. A synchronous `gesture.commit()` in that cleanup
   * therefore fires `onEditEnd` a millisecond after the editor appears — and
   * `LabeledPort` uses `onEditEnd` to LEAVE edit mode, so clicking a port's
   * label opened an editor that closed itself on the next tick. Measured in
   * the notebook lab (now /home/bam/marimo-canvas; ported from
   * claude/notebook-lab-work-order-472c22 `23ab20e`): `data-editing` flipped
   * true at t and false at t+2ms, and dropping `<StrictMode>` alone made the
   * feature work. It was invisible because nothing wrapped a `CodeEditor`
   * story in StrictMode, and because "does the editor open" reads identically
   * to "does it stay open" in any assertion that does not wait.
   *
   * Deferring to the next frame distinguishes the two cases without guessing:
   * a StrictMode remount re-runs this effect immediately and cancels the
   * pending commit, while a genuine unmount has nothing to cancel it and the
   * commit lands one frame later — on callbacks held in a ref, so a late call
   * is exactly as valid as the synchronous one was. `gesture` is created once
   * per mount (`gestureRef`), so the only re-run this effect ever sees is the
   * StrictMode replay, never a swap that would cancel a different gesture's
   * commit.
   */
  const pendingCommit = useRef<number | null>(null);
  useLayoutEffect(() => {
    if (pendingCommit.current !== null) {
      cancelAnimationFrame(pendingCommit.current);
      pendingCommit.current = null;
    }
    return () => {
      pendingCommit.current = requestAnimationFrame(() => {
        pendingCommit.current = null;
        gesture.commit();
      });
    };
  }, [gesture]);

  const width = wrap ? undefined : codeEditorWidthPx(columns, fontSizePx, lineNumbers, PADDING_X, PADDING_X);
  // §5's own words: "whole-field error also sets the existing
  // `ariaInvalid`" — an explicit `true` is never downgraded by an absent
  // error range; an explicit `false`/omitted still turns on the instant
  // ANY range in the list is `severity: "error"`.
  const hasErrorDiagnostic = (diagnostics ?? []).some((d) => d.severity === "error");
  const resolvedAriaInvalid = ariaInvalid || hasErrorDiagnostic;

  const boxStyle: CSSProperties = {
    fontSize: fontSizePx,
    ...(width !== undefined ? { width } : {}),
  };

  return (
    <div
      data-slot="code-editor"
      data-multiline={multiline}
      data-line-numbers={lineNumbers}
      data-overflow={overflow}
      data-language={language ? "set" : undefined}
      data-theme={typeof theme === "string" ? theme : theme?.id}
      className={`bbox-code-editor bbox-code-tokens${className ? ` ${className}` : ""}`}
      ref={hostRef}
      role="textbox"
      aria-label={ariaLabel}
      aria-describedby={ariaDescribedBy}
      aria-invalid={resolvedAriaInvalid ? true : undefined}
      aria-disabled={disabled ? true : undefined}
      aria-multiline={multiline ? true : undefined}
      data-testid={testId}
      // Theme vars sit BETWEEN boxStyle and the caller's own `style` — a
      // caller override (including a caller's own --bbox-tok-* variable)
      // still wins over the theme, same as it always won over boxStyle.
      style={{ ...boxStyle, ...codeEditorThemeVars(theme), ...style }}
      onPointerDown={(event) => event.stopPropagation()}
      onClick={(event) => event.stopPropagation()}
      onDoubleClick={(event) => event.stopPropagation()}
    />
  );
});

// src/components/codeEditorGesture.ts — ported by value from
// packages/bbox-ui/src/fieldGesture.ts, unchanged apart from doc references
// (CodeField → CodeEditor). Pure state machine, no CodeMirror/React import,
// so it carries over with nothing to strip.

/**
 * The live-commit contract `CodeEditor` follows.
 *
 * WHY a gesture object instead of "call `onWrite` on change, `onEditEnd` on
 * blur": a text field's edit is a *gesture* with three boundaries — it
 * begins, it produces values, and it ends exactly once — and how the field
 * was left (blur, Enter, Escape, the host unmounting the panel) only
 * decides *when* the gesture ends, never *whether* the value survives. The
 * browser will not tell you about the last one: no `blur` fires for a
 * focused element removed from the DOM, so a naive commit-on-blur field
 * silently drops whatever was typed the instant its panel unmounts. This
 * class is driven from the React lifecycle instead (`CodeEditor`'s unmount
 * effect calls `commit()`), where that boundary is observable.
 *
 * Two write policies, both loss-free:
 *
 * - `live` — every keystroke writes straight into the caller's store, so
 *   the store is the only copy of the text and there is nothing left to
 *   lose. `CodeEditor` uses this exclusively.
 * - `exit` — the value is buffered and written once, at the end boundary,
 *   for a write that is genuinely expensive. Still loss-free, because
 *   unmount is itself an end boundary.
 *
 * `begin` fires lazily, on the first keystroke that actually changes the
 * value, so a field that was merely focused leaves no trace in undo
 * history. `end` is the commit boundary a caller can hang a semantic
 * "rename" or a debounced round trip off, without the live write ever
 * having to wait for it.
 */

export type FieldCommitMode = "live" | "exit";

export interface FieldGestureHooks {
  /** Write the value. Per keystroke in `live`, once at the end in `exit`. */
  write(value: string): void;
  /**
   * Open one undoable step. Called lazily — on the first keystroke that
   * really changes the value — so merely focusing a field leaves no trace.
   */
  begin?(): void;
  /** The commit boundary. Fires exactly once per gesture, whatever ended it. */
  end?(value: string, startValue: string): void;
}

export class FieldGesture {
  mode: FieldCommitMode;

  private readonly hooks: FieldGestureHooks;
  private editing = false;
  private began = false;
  private start = "";
  private current = "";

  constructor(hooks: FieldGestureHooks, mode: FieldCommitMode = "live") {
    this.hooks = hooks;
    this.mode = mode;
  }

  get isEditing(): boolean {
    return this.editing;
  }

  get startValue(): string {
    return this.start;
  }

  get value(): string {
    return this.current;
  }

  /** Enter the field. Idempotent: re-entering keeps the original pre-edit value. */
  focus(value: string): void {
    if (this.editing) return;
    this.editing = true;
    this.began = false;
    this.start = value;
    this.current = value;
  }

  /** One keystroke, paste, or IME commit. */
  change(value: string): void {
    if (!this.editing) this.focus(this.current);
    if (value === this.current) return;
    this.current = value;
    if (this.mode !== "live") return;
    this.ensureBegun();
    this.hooks.write(value);
  }

  /**
   * End the gesture and keep the value. Every exit route calls this — blur,
   * Enter, Escape, and the unmount cleanup — so it must stay idempotent.
   */
  commit(): void {
    if (!this.editing) return;
    if (this.mode === "exit" && this.current !== this.start) {
      this.ensureBegun();
      this.hooks.write(this.current);
    }
    const value = this.current;
    const start = this.start;
    this.editing = false;
    this.began = false;
    this.hooks.end?.(value, start);
  }

  private ensureBegun(): void {
    if (this.began) return;
    this.began = true;
    this.hooks.begin?.();
  }
}

// src/components/codeEditorGuards.ts — ported by value from
// packages/bbox-ui/src/codeFieldGuards.ts, unchanged apart from doc
// references (CodeField → CodeEditor). Pure CodeMirror state logic, no
// React, nothing to strip.

import {
  Annotation,
  EditorState,
  Transaction,
  type AnnotationType,
  type Extension,
} from "@codemirror/state";

/**
 * Marks `CodeEditor`'s own imperative doc swaps (the `value`-prop sync) so
 * the change listener never echoes them back as typing. Lives here, not in
 * `codeEditor.tsx`, so `singleLineGuard` below can recognise and re-apply it
 * on a transaction it has to rebuild — annotations are not part of
 * CodeMirror's public `Transaction` surface (only `.annotation(type)` for a
 * type you already know to ask for, never an enumerable list), so the only
 * ones a filter can honestly preserve are ones it knows about by name.
 */
export const externalSync = Annotation.define<boolean>();

/**
 * The named annotations this guard knows how to detect and re-apply on a
 * transaction it has to rebuild: CodeMirror's own `Transaction.time` /
 * `userEvent` / `addToHistory` / `remote`, plus `externalSync` above.
 *
 * WHY this matters beyond bookkeeping: `userEvent` and `addToHistory` are
 * what `history()` groups undo steps by. Losing them made a rebuilt
 * transaction look like an ORDINARY edit with no origin and no history
 * opinion — inside CodeMirror's 500ms `newGroupDelay`, that merged
 * silently into whatever adjacent edit was already open. Type `P`, then
 * paste `a\nb` (copying a lane line with an empty selection is linewise
 * and carries a trailing `\n`, so this is common here): one Ctrl+Z used to
 * discard the typing AND the paste together, leaving `t: ` instead of
 * undoing the paste alone. `time` matters too — it feeds the SAME grouping
 * window, so a rebuilt transaction stamped with a fresh `Date.now()`
 * instead of the original's timestamp can drift outside the window the
 * original edit was actually inside.
 */
function knownAnnotations(tr: Transaction): Annotation<unknown>[] {
  const carried: Annotation<unknown>[] = [];
  function add<T>(type: AnnotationType<T>): void {
    const value = tr.annotation(type);
    if (value !== undefined) carried.push(type.of(value));
  }
  add(Transaction.time);
  add(Transaction.userEvent);
  add(Transaction.addToHistory);
  add(Transaction.remote);
  add(externalSync);
  return carried;
}

/** How many `\r`/`\n` characters sit in `text` before `pos` — the amount a position must shift left to land on the equivalent spot once those characters are removed. */
function newlinesBefore(text: string, pos: number): number {
  let count = 0;
  for (let i = 0; i < pos; i++) {
    const code = text.charCodeAt(i);
    if (code === 10 || code === 13) count++;
  }
  return count;
}

/**
 * A single-line `CodeEditor` must never contain a newline, by ANY path —
 * not just typed or pasted text (`EditorView.inputHandler` catches that
 * one, and stays for the tighter cursor placement it can do on a normal
 * keystroke) but also a COMMAND that inserts one directly, like
 * `defaultKeymap`'s `insertBlankLine` (reachable on Ctrl/Cmd+Enter when a
 * completion popup happens to be open and swallows the field's own exit
 * binding first). A `transactionFilter` sees every transaction regardless
 * of what produced it, so this is the actual guarantee, not a best effort
 * at the input layer.
 *
 * Things earlier passes at this got wrong, all fixed here:
 *
 * - The caret was clamped to the CLEANED text's length instead of shifted
 *   by how many stripped characters sat ahead of it.
 * - The replacement spec silently dropped every annotation and effect —
 *   `externalSync` (an external value-sync misread as typing) and, worse,
 *   CodeMirror's OWN `userEvent`/`addToHistory`/`time` (undo-grouping
 *   corruption — see `knownAnnotations`'s doc). `effects` are forwarded
 *   unconditionally (a plain array on `Transaction`, unlike annotations,
 *   which have no generic enumerable list); `scrollIntoView` likewise.
 * - A transaction that, once cleaned, changes the DOCUMENT not at all
 *   (pasting a bare `"\n"`, or pasting text that survives cleaning back to
 *   exactly what a replaced selection already said) either dispatched a
 *   pointless full document-replace (a dead undo step) or, at the other
 *   extreme, dropped the transaction so completely that a REPLACED
 *   SELECTION was left standing open instead of collapsed to where the
 *   paste actually ended — the very next keystroke would have overwritten
 *   the pasted text a second time. Both are handled by always computing
 *   the corrected selection and only including `changes` when the doc
 *   actually differs.
 */
export function singleLineGuard(isMultiline: () => boolean): Extension {
  return EditorState.transactionFilter.of((tr) => {
    if (isMultiline() || !tr.docChanged) return tr;
    const text = tr.newDoc.toString();
    if (!/[\r\n]/.test(text)) return tr;
    const cleaned = text.replace(/[\r\n]+/g, "");
    const { anchor, head } = tr.newSelection.main;
    const shift = (pos: number) => Math.max(0, Math.min(pos - newlinesBefore(text, pos), cleaned.length));
    const selection = { anchor: shift(anchor), head: shift(head) };
    const preserved = {
      effects: tr.effects,
      annotations: knownAnnotations(tr),
      scrollIntoView: tr.scrollIntoView,
    };
    if (cleaned === tr.startState.doc.toString()) {
      // Nothing textual changes, but the selection still has to land where
      // a real edit would have — a paste that replaced a selection with
      // (once cleaned) the same text it already held must still collapse
      // the selection to the end of the paste, not leave the old range
      // standing open for the next keystroke to clobber.
      return { selection, ...preserved };
    }
    return {
      changes: { from: 0, to: tr.startState.doc.length, insert: cleaned },
      selection,
      ...preserved,
    };
  });
}

// src/components/codeEditorHighlight.ts — the highlighter codeEditor.tsx
// mounts, replacing `syntaxHighlighting(classHighlighter)`.
//
// WHY a hand-written `HighlightStyle` and not `classHighlighter` (the stock
// @lezer/highlight highlighter this replaces): `classHighlighter`'s own
// rule table (node_modules/@lezer/highlight/dist/index.js) has no entry for
// `controlKeyword`, `definitionKeyword`, `moduleKeyword`, `operatorKeyword`,
// or either `function(...)` combination, so @lezer/highlight's own
// specificity fallback (a tag's `.set`, most-specific first) walks past all
// of them to the nearest ancestor tag that DOES have one. Measured on this
// exact tree (@lezer/highlight 1.2.3, @codemirror/lang-python 6.2.1):
//   controlKeyword / definitionKeyword / moduleKeyword / operatorKeyword
//     all collapse to plain `tags.keyword` -> "tok-keyword"
//   a call site, `function(variableName)` (e.g. `range(x)`), collapses to
//     `tok-variableName`; a method call, `function(propertyName)`
//     (e.g. `obj.foo()`), collapses to `tok-propertyName`
//   a Python/JS function DEFINITION is `function(definition(variableName))`
//     — its `.set` chain visits `definition(variableName)` (which DOES
//     have a classHighlighter rule, "tok-variableName tok-definition")
//     BEFORE it ever reaches plain `function(variableName)`, so it collapses
//     there and never reaches a "tok-function" class at all, at any
//     specificity level `classHighlighter` covers.
// In Dark Modern (Zach: "its important that people can set it to what they
// are used to") that means `if`/`return`/`for` render keyword-blue
// (#569cd6) instead of the correct control-purple (#c586c0), and a function
// name renders variable-blue (#9cdcfe) instead of the correct yellow
// (#dcdcaa) — the two most recognisable VS Code colours, both wrong. See
// codeEditorTheme.ts's own WHY on `--bbox-tok-control-keyword`/
// `--bbox-tok-function`, which have carried the right values the whole time
// with nothing ever emitting a class to hang them on.
//
// This file is `classHighlighter`'s own rule list (transcribed verbatim
// below, one rule per line matching its source order) PLUS the missing
// rules, each one UNIONING its class string with whatever `classHighlighter`
// already produced for that exact tag rather than replacing it — never
// "tok-controlKeyword" alone, always "tok-keyword tok-controlKeyword". Two
// reasons, both load-bearing:
//   1. `HighlightStyle`/`tagHighlighter` picks ONE map entry per token — the
//      first match walking that token's tag `.set` from most to least
//      specific — so a rule for the exact composed tag (e.g.
//      `function(definition(variableName))`) must be its own entry with
//      every class the token needs; you cannot "layer" two separate,
//      differently-specific entries and get both.
//   2. codeEditor.css's selectors were written expecting `classHighlighter`-
//      shaped input (a bare token gets exactly one ancestor's class) and
//      groups `tok-keyword`/`tok-operatorKeyword`/`tok-definitionKeyword`/
//      `tok-moduleKeyword` under ONE rule for exactly this reason — keeping
//      the old class present alongside the new one means every rule that
//      already worked keeps working unchanged, with the new, more specific
//      selector (`tok-controlKeyword`, `tok-function`) simply winning the
//      cascade tie by appearing later in that file. Dropping the old class
//      would also fail this file's own H1 unit test, which asserts the new
//      highlighter's class set is a strict superset of `classHighlighter`'s
//      for every token in real Python/JS/JSON source.
import { HighlightStyle } from "@codemirror/language";
import { tags } from "@lezer/highlight";

export const codeEditorHighlightStyle = HighlightStyle.define([
  // --- verbatim from @lezer/highlight's classHighlighter (1.2.3), same order ---
  { tag: tags.link, class: "tok-link" },
  { tag: tags.heading, class: "tok-heading" },
  { tag: tags.emphasis, class: "tok-emphasis" },
  { tag: tags.strong, class: "tok-strong" },
  { tag: tags.keyword, class: "tok-keyword" },
  { tag: tags.atom, class: "tok-atom" },
  { tag: tags.bool, class: "tok-bool" },
  { tag: tags.url, class: "tok-url" },
  { tag: tags.labelName, class: "tok-labelName" },
  { tag: tags.inserted, class: "tok-inserted" },
  { tag: tags.deleted, class: "tok-deleted" },
  { tag: tags.literal, class: "tok-literal" },
  { tag: tags.string, class: "tok-string" },
  { tag: tags.number, class: "tok-number" },
  { tag: [tags.regexp, tags.escape, tags.special(tags.string)], class: "tok-string2" },
  { tag: tags.variableName, class: "tok-variableName" },
  { tag: tags.local(tags.variableName), class: "tok-variableName tok-local" },
  { tag: tags.definition(tags.variableName), class: "tok-variableName tok-definition" },
  { tag: tags.special(tags.variableName), class: "tok-variableName2" },
  { tag: tags.definition(tags.propertyName), class: "tok-propertyName tok-definition" },
  { tag: tags.typeName, class: "tok-typeName" },
  { tag: tags.namespace, class: "tok-namespace" },
  { tag: tags.className, class: "tok-className" },
  { tag: tags.macroName, class: "tok-macroName" },
  { tag: tags.propertyName, class: "tok-propertyName" },
  { tag: tags.operator, class: "tok-operator" },
  { tag: tags.comment, class: "tok-comment" },
  { tag: tags.meta, class: "tok-meta" },
  { tag: tags.invalid, class: "tok-invalid" },
  { tag: tags.punctuation, class: "tok-punctuation" },

  // --- the rules classHighlighter is missing (this file's own WHY above) ---
  // Bare keyword subtags: each already falls under codeEditor.css's shared
  // `.tok-keyword, .tok-operatorKeyword, .tok-definitionKeyword,
  // .tok-moduleKeyword` selector, so keeping "tok-keyword" alongside the
  // specific class changes nothing about which rule matches for these
  // three — only `tok-controlKeyword` has its own separate CSS rule.
  { tag: tags.controlKeyword, class: "tok-keyword tok-controlKeyword" },
  { tag: tags.definitionKeyword, class: "tok-keyword tok-definitionKeyword" },
  { tag: tags.moduleKeyword, class: "tok-keyword tok-moduleKeyword" },
  { tag: tags.operatorKeyword, class: "tok-keyword tok-operatorKeyword" },
  // A function name at a call site (`range(x)`, `obj.foo()`): the bare
  // `function(...)` tag, one level more specific than classHighlighter's
  // own `variableName`/`propertyName` entries above.
  { tag: tags.function(tags.variableName), class: "tok-variableName tok-function" },
  { tag: tags.function(tags.propertyName), class: "tok-propertyName tok-function" },
  // A function/method DEFINITION (`def move(...)`, `function move(...)`):
  // its own most-specific entry, since `function(definition(variableName))`'s
  // `.set` chain reaches `definition(variableName)` (mapped above) before it
  // ever reaches the bare `function(variableName)` rule two lines up — see
  // this file's own WHY, point 1.
  {
    tag: tags.function(tags.definition(tags.variableName)),
    class: "tok-variableName tok-definition tok-function",
  },
  {
    tag: tags.function(tags.definition(tags.propertyName)),
    class: "tok-propertyName tok-definition tok-function",
  },
]);

// src/components/codeEditorLayout.ts — the columns → pixel-width maths,
// recovered from claude/code-block-primitive's packages/bbox-ui/src/
// codeBlock.layout.ts (`CODE_BLOCK_GUTTER_PX`, `CODE_BLOCK_CHAR_RATIO`,
// `codeBlockCharPx`, `codeBlockWidthPx`) after main's 368a524 dropped the
// whole `look`/preset ladder that file also carried. Trimmed to just the
// width maths — no size ladder, no look/overflow enum, no `grow`/
// `grow-truncated` (this app has no FieldSpec/preset machinery to hang
// those on). Pure numbers, no React, no CodeMirror.
//
// DONOR LINES (branch `claude/code-block-primitive`, tip dc30352, read
// 2026-09-17 — the branch is unmerged but present, so `git show
// claude/code-block-primitive:packages/bbox-ui/src/codeBlock.layout.ts`
// resolves these offline):
//   • `:111` `CODE_BLOCK_GUTTER_PX = 36`  -> `CODE_EDITOR_GUTTER_PX`
//   • `:112` `CODE_BLOCK_CHAR_RATIO = 0.61` -> `CODE_EDITOR_CHAR_RATIO`
//   • `:116` `codeBlockCharPx` body        -> `codeEditorCharPx`
//   • `:135` `codeBlockWidthPx` body       -> `codeEditorWidthPx`
// Renames only; the arithmetic is byte-identical. main's 368a524 is the
// commit that dropped the rest of that file.
//
// NO PRIOR ART IS CLAIMED. `0.61` is an EMPIRICAL constant — a measured
// glyph-advance ratio for one specific font stack, not a derived or
// published figure — and the width formula is plain addition. The honest
// caveat that goes with an empirical constant: it is only right for the
// `ui-monospace` stack it was measured on, and a host that swaps the font
// silently gets a wrong width. That is a known limitation, not a bug being
// reported here.

/** The line-number gutter's reserved width, and the mono-cell approximation
 * (glyph advance ≈ 0.61 × font-size for the ui-monospace stack) — both
 * SystemSketch's own measured constants, ported via codeBlock.layout.ts. */
export const CODE_EDITOR_GUTTER_PX = 36;
export const CODE_EDITOR_CHAR_RATIO = 0.61;

/** Width in px of one character cell at `fontPx`. */
export function codeEditorCharPx(fontPx: number): number {
  return Math.max(1, fontPx * CODE_EDITOR_CHAR_RATIO);
}

/**
 * The box width a CodeEditor takes to show `columns` characters — padding,
 * plus the gutter when line numbers are on, plus the cells. `columns` is
 * the AUTHORED fact ("100 ch"), pixels derive from it, never the other way
 * round. Returns `undefined` for `columns <= 0`, the "fill whatever the
 * host gives me" default.
 */
export function codeEditorWidthPx(
  columns: number,
  fontPx: number,
  lineNumbers: boolean,
  paddingLeft: number,
  paddingRight: number,
): number | undefined {
  if (!Number.isFinite(columns) || columns <= 0) return undefined;
  return Math.round(
    paddingLeft +
      paddingRight +
      (lineNumbers ? CODE_EDITOR_GUTTER_PX : 0) +
      Math.round(columns) * codeEditorCharPx(fontPx),
  );
}

// src/components/codeEditorTheme.ts — the palette-swap half of syntax
// theming (docs/FEEDBACK-2026-09-17b-PLAN.md A-2). `codeEditor.tsx` mounts
// `syntaxHighlighting(classHighlighter)` once and never touches it again;
// `classHighlighter` (@lezer/highlight) emits stable, colourless `tok-*`
// classes, and codeEditor.css is the one place those get a colour — under
// selectors that read `var(--bbox-tok-*, <today's literal>)`. A theme is
// therefore nothing but a map of those custom-property names to hex
// strings, applied inline on the editor root: no second highlighter, no
// per-theme `EditorView.theme()`. Pure data + one small resolver, no React
// import needed beyond the `CSSProperties` return type.
//
// WHY a palette swap and not a CodeMirror theme extension: `EditorView.theme()`
// reconfigures CodeMirror's own stylesheet machinery per instance — four
// themes would mean four compartmented extensions, reconciled against
// whatever `classHighlighter` already painted, fighting the same cascade
// this file's sibling CSS already resolved once (codeEditor.css's own WHY
// on selector specificity). A CSS variable is one inline `style` write, no
// CodeMirror reconfiguration, and it composes with a caller's own `style`
// override for free.
import type { CSSProperties } from "react";

export interface CodeEditorTheme {
  /** Stable id — what a `theme` prop or a `<select>`'s `value` carries. */
  id: string;
  /** Human label, e.g. "Dark Modern". */
  label: string;
  appearance: "dark" | "light";
  /** CSS custom properties (`--bbox-tok-*`), applied inline to the editor root. */
  vars: Record<string, string>;
}

