/* ------------------------------------------------------------------ */
/* Colour — state -> token, inlined from packages/bbox-ui's appearance.ts */
/* (STATE_TOKENS/paintVar), tone channel removed (D3) so there is no      */
/* color-mix blend step: a token resolves straight to `var(--token)`.     */
/* ------------------------------------------------------------------ */

/**
 * The board's four-value axis — "what is in the port": empty, a default
 * value set, wired to something, or data has flowed through it just now.
 * `dimmed`/`hidden` are NOT rungs of this union (see `PortProps`'s own
 * docs) — neither is a fact about what the port IS.
 */
export type PortState = "empty" | "valueSet" | "wired" | "received";

export const PORT_STATES: PortState[] = ["empty", "valueSet", "wired", "received"];

export const PORT_STATE_LABELS: Record<PortState, string> = {
  empty: "Empty",
  valueSet: "Default Value",
  wired: "Wired",
  received: "Data Received",
};

interface StateTokenPair {
  ring: string | null;
  fill: string | null;
  core: string | null;
}

const STATE_TOKENS: Record<PortState, StateTokenPair> = {
  empty: { ring: "foreground", fill: null, core: null },
  valueSet: { ring: "muted-foreground", fill: "muted", core: null },
  wired: { ring: "primary", fill: null, core: "primary" },
  received: { ring: "bbox-received", fill: "bbox-received", core: "bbox-received" },
};

/**
 * `primary` resolves through the bbox accent (with a fallback to whatever
 * host `--primary` already means) so "wired" reads as the design system's
 * own orange rather than the host's button colour — same special case
 * `paintVar` makes in the donor package. `--bbox-primary`/`--bbox-received`
 * are the two tokens this phase appends to `src/globals.css`.
 */
export function paintVar(token: string): string {
  return token === "primary" ? "var(--bbox-primary, var(--primary))" : `var(--${token})`;
}

/* ------------------------------------------------------------------ */
/* The dot's paint                                                     */
/* ------------------------------------------------------------------ */

export interface PortDotPaintInput {
  state?: PortState;
  dimmed?: boolean;
  hinting?: boolean;
  /**
   * Drag-time validity preview (docs/INVALID-STATES-PLAN.md D5, ruling 5)
   * — "on by default": whether THIS port is a legal target for the
   * connection currently being dragged. `undefined` means no gesture is
   * in flight (zero paint change — every pre-existing snapshot stays
   * byte-identical). Computed ONCE per gesture by the host
   * (`connectionAvailability`, scene kit) and handed down as paint; this
   * component never asks WHY a port is unavailable, only THAT it is —
   * ruling 2's layering rule, one prop over. Wins over `hinting`/`dimmed`
   * (see `portRingColor`'s own precedence doc) because it is the more
   * specific, more ephemeral, in-gesture fact.
   */
  availability?: "available" | "unavailable";
  /** The diagnostic axis (docs/INVALID-STATES-PLAN.md §5's Port row) — a
   *  judgement ABOUT the port, made by an external producer, never a fifth
   *  `state`. Only the worst severity present paints (`maxDiagnosticSeverity`,
   *  ./highlighter.tsx); the rest ride the flag's popover, not this mark. */
  diagnostics?: Diagnostic[];
  /** Which `HighlighterKind` draws the mark. Defaults to
   *  `DEFAULT_HIGHLIGHTER_KIND` ("stroke") — Zach's own lean from the
   *  report feedback; `"halo"` is the pre-existing treatment, kept as a
   *  sibling, not deleted. */
  highlighterKind?: HighlighterKind;
  /**
   * The visual variant in force (src/skin/portVariants.ts). Decides the
   * ring widths and which paint grammar maps `state` onto ring, disc and
   * core (`portGrammarPaint`). Defaults to v1 so every pure call site
   * (`sketchAtEdge`'s ring colour, a story computing a paint) gets the
   * default look without resolving anything; `Port` passes its own.
   */
  variant?: PortVariant;
  /**
   * The port's declared TYPE name — read only by the two by-type grammars
   * (v2 SystemSketch-original, v3 langflow), each through its own source's
   * palette (`portTypePaint`). Every other grammar ignores it: colour
   * comes from STATE there (the 2026-09-10 ruling).
   */
  dataType?: string;
  /** An explicit CSS colour for the type, winning over either palette. */
  typeColor?: string;
}

const DEFAULT_VARIANT = PORT_VARIANTS[DEFAULT_PORT_VARIANT_ID];

/**
 * Static half of the dot's class — sizing/shape/transition only. Every
 * colour fact is dynamic per state and lives in `portDotStyle` instead.
 *
 * Hover is a real CSS `:hover` pseudo-class, deliberately NOT a `hover`
 * prop — nothing outside this component ever needs to SET hover. Since
 * 2026-09-19 the hover rule lives in `src/skin/portVariants.css` (it
 * reads the variant's own `--bbox-port-hover-scale`/`-ring`), so the old
 * `hover:scale-110` utility is gone from here; `transition-transform`
 * (Tailwind v4: `transform, translate, scale, rotate`) still animates it.
 */
export function portDotClass(): string {
  return "relative box-border inline-flex shrink-0 rounded-full transition-transform duration-[50ms] ease-in-out motion-reduce:transition-none";
}

/**
 * The single place `availability` is folded into the pre-existing
 * `hinting`/`dimmed` paint facts (docs/INVALID-STATES-PLAN.md D5, ruling
 * 5's precedence: `availability > hinting > dimmed > state`). `undefined`
 * (no gesture in flight) passes `hinting`/`dimmed` through untouched — the
 * zero-paint-change contract every existing snapshot depends on.
 * `"available"` reuses `hinting`'s own shape outright; `"unavailable"`
 * reuses `dimmed`'s — each OVERRIDING the caller's own `hinting`/`dimmed`
 * rather than composing with them, because a port cannot simultaneously be
 * "the drag target" and "faded for being off-focus".
 */
function resolveAvailabilityPaint(
  availability: PortDotPaintInput["availability"],
  hinting: boolean,
  dimmed: boolean,
): { hinting: boolean; dimmed: boolean } {
  if (availability === "available") return { hinting: true, dimmed: false };
  if (availability === "unavailable") return { hinting: false, dimmed: true };
  return { hinting, dimmed };
}

/**
 * One grammar's answer for one state: the ring's colour, the disc's colour
 * (`null` = the card, i.e. hollow) and the centre's (`null` = no core span).
 *
 * WHY one table per grammar, not per-channel enums: the five sources
 * disagree about what a port's colour MEANS — STATE in this trunk (the
 * 2026-09-10 ruling), TYPE in the original SystemSketch and in langflow —
 * and about which circle carries it. Independent knobs would let two
 * grammars combine into a look nobody proposed; a switch keeps each variant
 * exactly what its source draws. Gesture facts (`hinting`, `dimmed`,
 * `availability`) are NOT grammar: they override every variant the same
 * way in `portRingColor`/`portDotStyle`/`portCoreStyle` below.
 */
export interface PortGrammarPaint {
  ring: string | null;
  fill: string | null;
  core: string | null;
}

export function portGrammarPaint(
  state: PortState,
  variant: PortVariant = DEFAULT_VARIANT,
  dataType?: string,
  typeColor?: string,
): PortGrammarPaint {
  const tokens = STATE_TOKENS[state];
  const tok = (token: string | null) => (token ? paintVar(token) : null);
  switch (variant.dot.grammar) {
    case "trunk":
      // v1 — this trunk's own three circles, unchanged; only the scale moved.
      return { ring: tok(tokens.ring), fill: tok(tokens.fill), core: tok(tokens.core) };
    case "systemsketch": {
      // v2 — block-canvas.css:1103-1132: the ring is ALWAYS the type's
      // colour; the disc is the card (unwired), muted (`.Port_default`,
      // owns a default), the type colour (`.Port_connected`). `received`
      // has no original counterpart, so it borrows the trunk's own token.
      const type = portTypePaint("systemsketch", dataType, typeColor)!;
      const fill = state === "valueSet" ? paintVar("muted-foreground") : state === "wired" ? type.disc : state === "received" ? paintVar("bbox-received") : null;
      return { ring: type.disc, fill, core: null };
    }
    case "langflow": {
      // v3 — handleRenderComponent/index.tsx:110-131: the disc IS the type
      // colour and the 3px ring its pale `-foreground` pair, in EVERY
      // state. langflow lets the cable say "wired" (a connected handle only
      // swaps to the SOURCE's colour, :144-145) — faithfully, so here.
      const type = portTypePaint("langflow", dataType, typeColor)!;
      return { ring: type.tint, fill: type.disc, core: null };
    }
    case "pearl":
      // v4 — React Flow UI `BaseHandle`: `bg-slate-100` + `border-slate-300`
      // at rest (neutral token mixes, so dark mode follows), stock xyflow
      // ink once wired (`--xy-handle-background-color-default: #1a192b`,
      // this app's `--foreground`), the trunk's received token for data.
      switch (state) {
        case "empty":
          return { ring: "color-mix(in srgb, var(--foreground) 24%, var(--card))", fill: "color-mix(in srgb, var(--foreground) 5%, var(--card))", core: null };
        case "valueSet":
          return { ring: "color-mix(in srgb, var(--foreground) 45%, var(--card))", fill: "color-mix(in srgb, var(--foreground) 22%, var(--card))", core: null };
        case "wired":
          return { ring: paintVar("foreground"), fill: paintVar("foreground"), core: null };
        case "received":
          return { ring: paintVar("bbox-received"), fill: paintVar("bbox-received"), core: null };
      }
      break;
    case "reticle":
      // v5 — DP - Port's three circles literally: the outline takes the
      // state colour, the background stays the card, the CENTRE is always
      // drawn — muted until something attaches, lit when wired.
      return {
        ring: tok(tokens.ring),
        fill: null,
        core: tok(tokens.core) ?? (state === "valueSet" ? paintVar("muted-foreground") : "color-mix(in srgb, var(--foreground) 32%, var(--card))"),
      };
  }
  return { ring: tok(tokens.ring), fill: tok(tokens.fill), core: tok(tokens.core) };
}

/**
 * The dot's ring colour, as one exported derivation.
 *
 * WHY extracted rather than left inline (ported from packages/bbox-ui/src/
 * port.tsx's own `portRingColor`): the sketch skin draws the ring as a
 * path instead of as box-shadow layers, and it has to be the SAME colour.
 * A second copy of this precedence is exactly how a `hinting` port would
 * end up orange in one skin and grey in another. `null` means "this state
 * paints no ring at all". Precedence: see `resolveAvailabilityPaint`'s doc
 * — gesture facts first, then the variant's grammar.
 */
export function portRingColor({
  state = "empty",
  dimmed = false,
  hinting = false,
  availability,
  variant = DEFAULT_VARIANT,
  dataType,
  typeColor,
}: PortDotPaintInput): string | null {
  const effective = resolveAvailabilityPaint(availability, hinting, dimmed);
  if (effective.hinting) return paintVar("primary");
  if (effective.dimmed) return paintVar("muted-foreground");
  return portGrammarPaint(state, variant, dataType, typeColor).ring;
}

/**
 * The dot's ring/fill, per the variant's grammar (`portGrammarPaint`).
 * `dimmed` forces the ring to `muted-foreground` and
 * fades the whole dot to ~45% opacity, leaving the resting fill/core colour
 * underneath untouched (a dimmed `wired` port still reads "wired, just not
 * focused right now"). `hinting` wears `wired`'s own shape (hollow ring, lit
 * core) in the accent colour regardless of `state` — previewing the port
 * BECOMING wired, with a wide halo. `availability` picks between these two
 * shapes outright — see `resolveAvailabilityPaint`'s doc.
 */
export function portDotStyle({
  state = "empty",
  dimmed = false,
  hinting = false,
  availability,
  diagnostics,
  highlighterKind = DEFAULT_HIGHLIGHTER_KIND,
  variant = DEFAULT_VARIANT,
  dataType,
  typeColor,
}: PortDotPaintInput): CSSProperties {
  const effective = resolveAvailabilityPaint(availability, hinting, dimmed);
  const ringColor = portRingColor({ state, dimmed, hinting, availability, variant, dataType, typeColor });
  // `hinting` (or `availability: "available"`) renders hollow (no fill),
  // matching `wired`'s own shape on the default grammar.
  const fillColor = effective.hinting ? null : portGrammarPaint(state, variant, dataType, typeColor).fill;
  const gapPx = variant.dot.gap;
  // The drag preview rings a port one step heavier than its resting ring.
  const stateRingPx = effective.hinting ? variant.dot.ring + 1 : variant.dot.ring;

  const layers: string[] = [];
  if (ringColor != null) {
    // The card-coloured punch-out first (0 on the ring-only variants), then
    // the ring — the same two-layer recipe the fixed 2/3px rings used.
    if (gapPx > 0) layers.push(`0 0 0 ${gapPx}px var(--card)`);
    layers.push(`0 0 0 ${gapPx + stateRingPx}px ${ringColor}`);
  }
  if (effective.hinting) {
    layers.push("0 0 0 9px color-mix(in srgb, var(--bbox-primary, var(--primary)) 38%, transparent)");
  }
  // WHY APPENDED, not prepended (docs/INVALID-STATES-PLAN.md §3: "state
  // ring/fill untouched"): CSS box-shadow layers paint front-to-back in
  // list order — the FIRST layer wins any overlap. The state ring's own
  // two layers above are already opaque out to their own radius; appending
  // this translucent wash puts it strictly BEHIND them, so it can only
  // ever show in the band beyond the state ring (identical geometry to
  // `hinting`'s own halo just above — same reuse §5's Port row calls for).
  // Prepending would alpha-blend it OVER the opaque state ring instead,
  // recolouring the very fact this axis must not touch.
  // `info` paints NOTHING on a Port (§5's own table) — only error/warning
  // earn a mark, in whichever `highlighterKind` the caller asked for.
  const diagnosticSeverity = maxDiagnosticSeverity(diagnostics);
  if (diagnosticSeverity && diagnosticSeverity !== "info") {
    const color = diagnosticColorVar(diagnosticSeverity);
    if (highlighterKind === "halo") {
      layers.push(`0 0 0 9px color-mix(in srgb, ${color} 38%, transparent)`);
    } else {
      // `stroke` and `mask` are the IDENTICAL geometry on a circle
      // (HighlighterKind's own doc: the equidistant offset of a circle is
      // trivially a larger circle — there is no corner for `mask` to get
      // more right than `stroke` does). A crisp two-layer ring — a card-
      // coloured gap, then a solid line — one step further out than the
      // state ring, the SAME two-layer recipe that ring itself already
      // uses one step in.
      const gap = gapPx + stateRingPx + 2;
      layers.push(`0 0 0 ${gap}px var(--card)`);
      layers.push(`0 0 0 ${gap + 2}px ${color}`);
    }
  }

  const style: CSSProperties = {};
  // Behind a token so the sketch skin can blank the CSS rings and let the
  // drawn one (below, in `Port`) take their place. Undefined on every other
  // skin, so the `var()` fallback IS the layer list and nothing changes.
  if (layers.length > 0) style.boxShadow = `var(--bbox-skin-dot-rings, ${layers.join(", ")})`;
  // Opaque resting paint, never transparent — a wall-mounted dot straddles a
  // block's border, and a transparent interior would let it show through a
  // hollow (`empty`/`wired`) dot. `var(--card)` is the same token the 2px
  // surface ring already uses, so ring and disc read as one punch-out.
  style.background = fillColor ?? "var(--card)";
  if (effective.dimmed && !effective.hinting) style.opacity = 0.45;
  if (effective.hinting) style.transform = "scale(1.18)";
  return style;
}

/** The core's own diameter as a fraction of the dot's. */
const PORT_CORE_RATIO = 0.42;
/** Below this box the 0.42 core is a 2px speck; a half-box core (3px in
 *  the 6px default) is the smallest pinhead that still reads as "lit". */
const PORT_CORE_RATIO_SMALL = 0.5;
const PORT_CORE_SMALL_BOX_PX = 8;

export function portCoreRatio(diameterPx: number): number {
  return diameterPx <= PORT_CORE_SMALL_BOX_PX ? PORT_CORE_RATIO_SMALL : PORT_CORE_RATIO;
}

/**
 * The small inner "core" dot — the THIRD of DP - Port's three circles. On
 * the default grammar it is lit for `wired` (disc stays hollow, core lit
 * instead of a solid fill) and `received` (core matches the already-solid
 * fill, reading as "fully lit"); the reticle grammar draws it in every
 * state; the solid-disc grammars never do (the whole disc carries it).
 * `null` means no core layer at all, not a transparent one.
 * `availability: "available"` lights the core the same way `hinting` does
 * (see `resolveAvailabilityPaint`'s doc); `"unavailable"` has no core
 * treatment of its own, same as `dimmed`.
 */
export function portCoreStyle({
  state = "empty",
  hinting = false,
  availability,
  variant = DEFAULT_VARIANT,
  dataType,
  typeColor,
}: PortDotPaintInput): CSSProperties | null {
  const effectiveHinting = resolveAvailabilityPaint(availability, hinting, false).hinting;
  if (effectiveHinting) return { background: paintVar("primary") };
  const core = portGrammarPaint(state, variant, dataType, typeColor).core;
  return core == null ? null : { background: core };
}

/* ------------------------------------------------------------------ */
/* Port — the dot alone: the disc + both rings + the lit core + the    */
/* 40px hit halo. Knows nothing about labels or slots.                 */
/* ------------------------------------------------------------------ */

export interface PortProps extends ComponentProps<"span"> {
  state?: PortState;
  diameter?: PortSize;
  /** Author-set, persisted. Genuinely absent when true — `if (hidden)
   * return null`, no element, no 40px halo, no pointer events at all. Not
   * "opacity 0, still clickable" — Zach's own annotation on the sketch:
   * "Completely remove it, we don't want it to be selectable either." */
  hidden?: boolean;
  /** Host-set, never persisted — the port is out of focus, or mid-drag and
   * not a legal target. Composes OVER the resting paint (a dimmed `wired`
   * port stays legible as "wired, unfocused"), never a fifth `state`. */
  dimmed?: boolean;
  /** Host-set, never persisted — the pointer is over this port mid-drag,
   * previewing it becoming `wired`. */
  hinting?: boolean;
  /** See `PortDotPaintInput.availability`'s own doc — drag-time validity
   *  preview (ruling 5), on by default at the host level. `undefined`
   *  (no gesture) is a zero-paint-change no-op; wins over `hinting`/
   *  `dimmed` when set. Emits `data-availability`. */
  availability?: "available" | "unavailable";
  /** The diagnostic axis — see `PortDotPaintInput.diagnostics`'s own doc.
   *  Absent or `[]` paints no mark at all. Hovering the dot shows every
   *  message (`DiagnosticTooltip`, ./highlighter.tsx); there is no flag
   *  here — Port is the dot alone, and §5 puts the flag on the composites
   *  that HAVE a corner or a slot to anchor it (`LabeledPort`, `Block`). */
  diagnostics?: Diagnostic[];
  /** See `PortDotPaintInput.highlighterKind`'s own doc. */
  highlighterKind?: HighlighterKind;
  /**
   * The hit halo's diameter in the component's OWN px. Defaults to
   * `PORT_HIT_PX` (40). The constant is scene-space: under a host's
   * viewport transform it scales with zoom. A host that wants a
   * screen-constant target divides by its own zoom before passing —
   * per ARCHITECTURE.md the host owns the viewport transform, so the
   * current zoom is an input here, never something Port measures.
   */
  hitPx?: number;
  /**
   * Paint the hit halo (translucent wash + dashed outline) so the region
   * is visible. Pure paint on the EXISTING halo span — geometry and
   * hit-testing are identical with this on or off, same rule as
   * `PortEdge`'s `showCard` overlay.
   */
  showHitRegion?: boolean;
  /**
   * The visual variant (src/skin/portVariants.ts). Omit — the normal case
   * — and the document-wide `<html data-bbox-port-variant>` decides,
   * defaulting to `v1`; set it to pin THIS port (a gallery showing all
   * five at once). When `diameter` is also omitted the variant's own dot
   * diameter is used, which is how "the small pair is the default" reaches
   * every port nobody sized explicitly.
   */
  variant?: PortVariantId;
  /**
   * Host-set, never persisted — the port is the current selection. Emits
   * `data-selected`; the outline is a CSS rule in portVariants.css sized
   * by the variant. Like `dimmed`, a modifier layered over the state, never
   * a fifth `state` (DP - Port: "Hover and out-of-focus are modifiers, not
   * states").
   */
  selected?: boolean;
  /**
   * How many cables meet this port (Zach, 2026-09-19: "The port only should
   * have 1 connection point in the center. Instead you should show the
   * producer circle that has the number for the number of arrows
   * intersecting at that port"). Rendered as a small count circle riding
   * the dot when 2 or more — a lone cable is the ordinary wired look and
   * a "1" on every wired port would be noise (the original SystemSketch's
   * own rule, `bboxUi/core/port.tsx:336`, `producers >= 2`). The number is
   * fed by the host (lane `producers-count` computes it from the scene);
   * this component only draws what it is handed.
   */
  producers?: number;
  /**
   * Which side of the dot the producers circle rides — the side AWAY from
   * the label, so it never sits on the text. `LabeledPort` derives it from
   * the label's origin; a bare `Port` defaults to `right`.
   */
  producersAt?: "left" | "right";
  /** See `PortDotPaintInput.dataType` — only the by-type variants read it. */
  dataType?: string;
  /** See `PortDotPaintInput.typeColor`. */
  typeColor?: string;
}

/**
 * The dot alone. `hidden` renders NOTHING — not a fifth visual state, a
 * visibility fact (see `PortProps.hidden`'s own doc, and Port.stories.tsx's
 * `Hidden` story, which asserts the DOM node is actually gone).
 */
export function Port({
  state = "empty",
  diameter,
  hidden = false,
  dimmed = false,
  hinting = false,
  availability,
  diagnostics,
  highlighterKind = DEFAULT_HIGHLIGHTER_KIND,
  hitPx = PORT_HIT_PX,
  showHitRegion = false,
  variant: variantId,
  selected = false,
  producers,
  producersAt = "right",
  dataType,
  typeColor,
  className,
  style,
  ...props
}: PortProps) {
  // Hooks before the early return — `hidden` is a prop, not a hook order.
  const variant = usePortVariant(variantId);
  if (hidden) return null;
  const diameterPx = diameter === undefined ? variant.dot.diameter : typeof diameter === "number" ? diameter : PORT_DIAMETERS[diameter];
  // A fixed 40px hit target regardless of the painted diameter.
  const haloInset = (diameterPx - hitPx) / 2;
  const coreStyle = portCoreStyle({ state, hinting, availability, variant, dataType, typeColor });
  const ringColor = portRingColor({ state, dimmed, hinting, availability, variant, dataType, typeColor });
  const ringExpansion = portVariantRingExpansion(variant);
  const diagnosticSeverity = maxDiagnosticSeverity(diagnostics);
  const showProducers = producers != null && producers >= 2;
  const producersOffset = showProducers ? portProducersOffsetPx(variant, producersAt) : null;
  const typePaint = portTypePaint(variant.dot.grammar, dataType, typeColor);
  return (
    // Hover -> Tooltip (message + code, no actions) is §5's interaction
    // contract for "any marked text/dot"; absent/empty `diagnostics`
    // returns `children` untouched, so a Port with no marks pays zero DOM
    // cost (see ./diagnostic.tsx's own header).
    <DiagnosticTooltip diagnostics={diagnostics}>
    <span
      data-slot="port-dot"
      data-state={state}
      data-diameter={diameter ?? diameterPx}
      data-dimmed={dimmed || undefined}
      data-hinting={hinting || undefined}
      data-selected={selected || undefined}
      data-availability={availability}
      data-diagnostic={diagnosticSeverity}
      data-highlighter-kind={diagnosticSeverity ? highlighterKind : undefined}
      // The variant this dot resolved to — the same attribute a host stamps
      // on `<html>`, republished per port so a CSS-only reader (or a
      // screenshot diff) can tell which look painted without walking up.
      {...{ [PORT_VARIANT_ATTR]: variant.id }}
      // WHY these two: docs/peps/0001-sketch-skin-at-the-boundary.md M4.
      // The dot's state rings are `box-shadow` layers, entirely OUTSIDE
      // this element's own box, so a boundary pass needs to know how far
      // out its drawn ring has to land. Before this migration that lived
      // only in `sketchAtEdge.ts`'s `ringExpansion`, which parsed this
      // element's computed `box-shadow` spreads back out — "DOM
      // archaeology" by its own header, kept only because that lane could
      // not edit this file. Now that it can, these publish the SAME two
      // numbers directly (unchanged arithmetic: the ring's own centre-line
      // sits `GAP*2 + RING*3` beyond the dot's diameter, drawn with a
      // `RING`-wide pen — now over the VARIANT's rings, `portVariantRing-
      // Expansion`, rather than fixed constants) and the parser is deleted.
      data-bbox-ring-expand={ringExpansion.expand}
      data-bbox-ring-pen={ringExpansion.pen}
      // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M7. Same gap as
      // Badge's — the edge's default seed is geometry (`${w}x${h}`), this
      // component's own is semantic (`port:${state}:${diameter}`).
      // Publishing it makes the wobble pattern match what the deleted
      // in-core `SketchOutline` call used to draw, not just its amplitude.
      data-bbox-seed={`port:${state}:${diameter ?? diameterPx}`}
      className={cn(portDotClass(), className)}
      style={{
        width: diameterPx,
        height: diameterPx,
        // The variant's numbers, published as custom properties so the
        // hover/selected/producers rules in portVariants.css (and any
        // CSS-only consumer below this element) read THIS dot's variant.
        ...portVariantVars(variant),
        // The type colour the by-type variants painted with — what the
        // langflow hover glow in portVariants.css reads.
        ...(typePaint ? ({ "--bbox-port-type-color": typePaint.disc } as CSSProperties) : null),
        ...portDotStyle({ state, dimmed, hinting, availability, diagnostics, highlighterKind, variant, dataType, typeColor }),
        // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M6. The ring's
        // colour is STATE-owned (computed above by `portRingColor`, not the
        // skin), so it is published in a channel the skin never writes,
        // rather than left for a boundary pass to read back off
        // `getComputedStyle(el).borderColor` — the sketch skin blanks that
        // to transparent on purpose (its mechanism for hiding a crisp line
        // while keeping its width), which would draw an invisible ring.
        // Naming a colour this component already computed is not a skin
        // import.
        ...({ "--bbox-ink-state": ringColor ?? undefined } as CSSProperties),
        ...style,
      }}
      {...props}
    >
      <span
        data-slot="port-dot-halo"
        aria-hidden
        className="absolute rounded-full"
        style={{
          inset: haloInset,
          // Paint-only when shown: background/outline never move geometry,
          // and the halo is the REAL hit element either way — so the drawn
          // region cannot disagree with the target it visualises.
          ...(showHitRegion
            ? { background: HIT_REGION_FILL, outline: HIT_REGION_OUTLINE, outlineOffset: -1 }
            : null),
        }}
      />
      {coreStyle && (
        <span
          data-slot="port-dot-core"
          aria-hidden
          className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full"
          style={{ width: `${portCoreRatio(diameterPx) * 100}%`, height: `${portCoreRatio(diameterPx) * 100}%`, ...coreStyle }}
        />
      )}
      {showProducers && producersOffset && (
        // The producers count circle, riding the dot up-and-outward on the
        // side away from the label, overlapping the painted ring by 2px like
        // a notification badge (geometry + WHY: `portProducersOffsetPx`).
        // Inside this span on purpose: it scales with the dot on hover and
        // dims with it, and a wire host that resolves a port by
        // `[data-slot="port-dot"]` never mistakes it for a second attach
        // point (it is `pointer-events: none` and not a dot). Paint lives in
        // portVariants.css; `data-style` picks ink vs. the original's soft
        // chip.
        <span
          data-slot="port-producers"
          data-count={producers}
          data-style={variant.producers.style}
          aria-label={`${producers} producers`}
          style={{
            left: `calc(50% + ${producersOffset.dx}px)`,
            top: `calc(50% + ${producersOffset.dy}px)`,
            transform: "translate(-50%, -50%)",
          }}
        >
          {producers}
        </span>
      )}
    </span>
    </DiagnosticTooltip>
  );
}

// src/components/tooltip.tsx — copied verbatim from
// apps/docs/src/registry/new-york-v4/ui/tooltip.tsx (the stock shadcn
// `new-york` Tooltip over Base UI's Tooltip primitive). packages/inspector
// also has a tooltip.tsx, but it's coupled to the dock's own portal
// container and z-index stack (`dockPortalContainer()`, `z-[320]`) — plumbing
// this standalone app doesn't have, so the docs version is the cleaner,
// self-contained pick. Only the `cn` import path changed to match this
// app's own src/lib/utils.ts.
"use client";

import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";

import { cn } from "../lib/utils";

function TooltipProvider({ delay = 0, ...props }: TooltipPrimitive.Provider.Props) {
  return <TooltipPrimitive.Provider data-slot="tooltip-provider" delay={delay} {...props} />;
}

function Tooltip({ ...props }: TooltipPrimitive.Root.Props) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
}

function TooltipTrigger({ ...props }: TooltipPrimitive.Trigger.Props) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

function TooltipContent({
  className,
  side = "top",
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  anchor,
  collisionPadding,
  container,
  children,
  style,
  ...props
}: TooltipPrimitive.Popup.Props &
  // WHY `anchor` was added to this Pick (2026-09-18, menu kit build): same
  // reason as dropdown-menu.tsx's matching edit — a canvas-anchored hint (a
  // pointer-position tooltip with no DOM trigger) needs Positioner's own
  // `anchor` (a Floating UI VirtualElement), which this Pick never
  // surfaced. Adds-only; every current consumer that omits `anchor` is
  // unaffected.
  //
  // `collisionPadding` and `container` followed in the same pass that fixed
  // dropdown-menu.tsx — see the longer note there. The pair has to stay in
  // lockstep across these two files: a host that scopes its design tokens
  // to a container element and gets themed MENUS but unthemed TOOLTIPS has
  // a bug that is much harder to read than one where neither works.
  Pick<
    TooltipPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset" | "anchor" | "collisionPadding"
  > &
  Pick<TooltipPrimitive.Portal.Props, "container">) {
  return (
    <TooltipPrimitive.Portal container={container}>
      <TooltipPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        anchor={anchor}
        collisionPadding={collisionPadding}
        className="isolate z-50"
      >
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          className={cn(
            "data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-[state=delayed-open]:animate-in data-[state=delayed-open]:fade-in-0 data-[state=delayed-open]:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 inline-flex items-center gap-1.5 px-3 py-1.5 text-xs has-data-[slot=kbd]:pr-1.5 **:data-[slot=kbd]:relative **:data-[slot=kbd]:isolate **:data-[slot=kbd]:z-50 **:data-[slot=kbd]:rounded-sm data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2 z-50 w-fit max-w-xs origin-(--transform-origin) bg-foreground text-background",
            className,
          )}
          // The skin seam (src/skin/skin.ts + skin.css) — `rounded-md`
          // moved off the class list above and onto here so a skin can
          // reach it; `var(--radius-md)` is exactly what it resolved to,
          // so a consumer who never imports skin.css is byte-identical.
          style={{ borderRadius: "var(--bbox-skin-radius, var(--radius-md))", ...style }}
          {...props}
        >
          {children}
          <TooltipPrimitive.Arrow className="size-2.5 translate-y-[calc(-50%-2px)] rotate-45 rounded-[2px] data-[side=inline-end]:top-1/2! data-[side=inline-end]:-left-1 data-[side=inline-end]:-translate-y-1/2 data-[side=inline-start]:top-1/2! data-[side=inline-start]:-right-1 data-[side=inline-start]:-translate-y-1/2 z-50 bg-foreground fill-foreground data-[side=bottom]:top-1 data-[side=left]:top-1/2! data-[side=left]:-right-1 data-[side=left]:-translate-y-1/2 data-[side=right]:top-1/2! data-[side=right]:-left-1 data-[side=right]:-translate-y-1/2 data-[side=top]:-bottom-2.5" />
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// src/skin/portVariants.ts — the port's VISUAL VARIANT registry: five
// circular, on-the-edge port styles, selectable by one attribute on
// `<html>` (`<html data-bbox-port-variant="v3">`) or by an explicit
// `variant` prop, defaulting to `v1`.
//
// Zach, 2026-09-19 (docs/ASK-2026-09-19-PORTS-EDGES-REGIONS-FEEDBACK.md):
// "the ports look way too big right now and the port text size also seems
// too big … generally it looks very unprofessional … I want the port text
// to be 'small' by default … one proposal should be based on the original
// SystemSketch source code, one on langflow … I only want to see proposals
// that explore circular ports … proposals where the ports are on the edge,
// not where they are inset."
//
// WHAT A VARIANT DECIDES — and only this: the dot's box diameter, the two
// rings painted OUTSIDE that box (the card-coloured `gap`, then the `ring`),
// which PAINT GRAMMAR maps the value state (empty · valueSet · wired ·
// received) onto those three circles, the label/type typography, and the
// hover / selected / producers-circle treatments. It never decides WHERE a
// dot sits: every variant is centred ON the block wall, half outside, by
// `BlockPort`'s rail geometry — the one rule that is not a proposal (the
// anti-example is `115744`, square handles inset inside the node body).
//
// WHY every variant keeps the SAME text rung (`xs`, 12px): "small by
// default" is the one thing Zach ruled outright, and the next rung up
// (`sm`, 18px) is exactly the size he called too big. So the five vary
// what a reviewer actually compares at that size — dot scale (11 → 16px
// painted), fill grammar, colour source (state vs. type), typeface and
// weight — and the text never jumps when he flips between them.
//
// WHY CSS custom properties AND a typed table, not one or the other: the
// components need NUMBERS (a label is placed from the dot's box, the sketch
// skin's boundary pass reads `data-bbox-ring-expand`), so this table is the
// source of truth and every port root publishes its resolved variant as
// inline `--bbox-port-*` properties. `portVariants.css` carries the SAME
// values under `[data-bbox-port-variant]` blocks for CSS-only consumers
// (the regions lane's frame inset, a host's chrome) and holds the
// hover/selected/producers rules that read them. `PortVariants.stories.tsx`'s
// `CssMirrorAgrees` pins the two together, the way `skin.test.ts` pins
// skin.css to skin.ts.
//
// WHY a MutationObserver-backed hook rather than React context: the ASK's
// contract is "CSS custom properties + data attributes, no React context
// needed — so the app switch and the Storybook global are three lines
// each". A host stamps the attribute; every mounted port re-resolves on its
// own. `useSyncExternalStore` makes that a real subscription, not a
// read-once-at-mount.
//
// PROVENANCE — every number below was read from a file on disk or a source
// fetched on 2026-09-19 (paths are the ones this lane read; the langflow
// clone is a shallow `git clone` of langflow-ai/langflow into the session
// scratchpad, cited by its repo-relative path):
//
//   v1  React Flow's own handle SCALE — `@xyflow/react/dist/style.css:250-251`
//       (`width: 6px; height: 6px`), `:274-278` (`.react-flow__handle-left
//       { left: 0; transform: translate(-50%, -50%) }` — centred ON the
//       edge) — drawn in THIS trunk's three-circle state grammar
//       (`port.tsx` STATE_TOKENS; `DP - Port.md` "Anatomy": outline,
//       background, centre) so every value state stays readable and the
//       colour still comes from STATE, per the 2026-09-10 ruling recorded
//       in `systemsketch/src/bboxUi/core/port.tsx:58-64`.
//   v2  the original SystemSketch live port —
//       `systemsketch/src/blocks/ui/block-canvas.css:1099-1132` ("The 12px
//       pyblocks dot: hollow while unwired, neutral-filled when it owns a
//       default, type-filled once a cable lands. The surface gap and
//       type-coloured outer ring…": 12px disc, `0 0 0 2px surface`, `0 0 0
//       3px var(--port-color)`), its palette `systemsketch/src/blocks/ui/
//       portPalette.ts:23-40`, the monospace signature row
//       `block-canvas.css:1035-1052` (`.BlockNode-portName` /
//       `.BlockNode-portType`, ui-monospace, type muted), and the count pill
//       `block-canvas.css:1453-1478` (`.Port-count`: surface-active fill,
//       muted 600 text, riding OUTSIDE the dot). Scaled ×2/3 with the text
//       (18px → 12px): disc 12 → 8, gap 2 → 1, ring 1 → 1.
//   v3  langflow — `src/frontend/src/CustomNodes/GenericNode/components/
//       handleRenderComponent/index.tsx`: `:128-131` a 10px `rounded-full`
//       disc whose background IS the type colour, `:110-113` a resting
//       `0 0 0 3px <datatype-X-foreground>` pale ring, `:114-123` a neon
//       glow only while hovered/open, `:24-32` a 32px transparent hit target
//       (our 40px halo); the colour names `src/frontend/src/utils/
//       styleUtils.ts:171-215` (`nodeColorsName`) → `src/frontend/src/style/
//       index.css:162-202` (`--datatype-*` light HSL pairs); unknown types
//       fall to gray (`src/frontend/src/CustomNodes/helpers/
//       get-node-output-colors-name.ts:12`). Label weight: `NodeInputField/
//       index.tsx:181` `text-sm font-medium`.
//   v4  React Flow UI (the shadcn registry for React Flow, reference #6 in
//       `/home/bam/pyblocks/reports/media/react-flow-references.md`) —
//       `https://ui.reactflow.dev/registry/base-handle.json` (fetched
//       2026-09-19): `BaseHandle` is `h-[11px] w-[11px] rounded-full border
//       border-slate-300 bg-slate-100`; `labeled-handle.json`: the label is
//       `text-foreground px-3`; `database-schema-node.json`: rows are
//       `text-xs`. A connected handle takes the stock React Flow ink
//       (`style.css:36` `--xy-handle-background-color-default: #1a192b`).
//   v5  Zach's own `DP - Port.md` ("three stacked circles — outline,
//       background, centre … every state in the visual grammar is some
//       combination of those three") drawn literally: a hairline outline, a
//       card background, and a centre that is ALWAYS present — muted until
//       something attaches — so the one centre attach point he asked for
//       ("edges should always leave from the center of the port") is
//       visible before any cable exists.

import { useSyncExternalStore, type CSSProperties } from "react";

import { PORT_DIAMETERS, PORT_TEXT_SIZES, type PortTextSize } from "../components/port.layout";

/* ------------------------------------------------------------------ */
/* Vocabulary                                                          */
/* ------------------------------------------------------------------ */

/** WHY the array is the source and the type is derived: same reason as
 *  `BBOX_SKINS` — a total `Record<PortVariantId, …>` below becomes a compile
 *  error until a sixth variant says what it paints. */
export const PORT_VARIANT_IDS = ["v1", "v2", "v3", "v4", "v5"] as const;
export type PortVariantId = (typeof PORT_VARIANT_IDS)[number];

export const DEFAULT_PORT_VARIANT_ID: PortVariantId = "v1";

/** The attribute a host stamps on `<html>`. Dataset spelling:
 *  `document.documentElement.dataset.bboxPortVariant`. */
export const PORT_VARIANT_ATTR = "data-bbox-port-variant";

/**
 * Which paint grammar maps the value state onto the three circles — ring,
 * disc, core. One per source, because the sources genuinely disagree about
 * what a port's colour MEANS (state here, type in SystemSketch-original and
 * langflow) and a bag of independent enums would let two of them combine
 * into a sixth look nobody proposed. `port.tsx`'s `portGrammarPaint` is the
 * one switch over it.
 */
export type PortGrammar = "trunk" | "systemsketch" | "langflow" | "pearl" | "reticle";

/** The resting disc, named for the reader of the table — the grammar decides
 *  the actual colour per state. */
export type PortDotFill = "hollow" | "typeOnWire" | "type" | "pearl" | "centre";

export interface PortVariantDot {
  /** The `[data-slot="port-dot"]` box, px — what `getBoundingClientRect` reads. */
  diameter: number;
  /** The card-coloured punch-out ring between disc and ring, px (0 allowed). */
  gap: number;
  /** The outer ring's stroke, px. */
  ring: number;
  fill: PortDotFill;
  grammar: PortGrammar;
}

export interface PortVariant {
  id: PortVariantId;
  title: string;
  /** One line naming the source this variant was read from. */
  basedOn: string;
  dot: PortVariantDot;
  /** The label's text rung (`PORT_TEXT_SIZES`). */
  text: PortTextSize;
  label: { weight: 400 | 500 | 600; font: "sans" | "mono" };
  /** The secondary run — the type — beside the label. */
  type: { size: PortTextSize; opacity: number };
  /** Real CSS `:hover` on the dot — scale factor, an extra soft outline
   *  (px, 0 = none) and whether it glows in the type colour (langflow). */
  hover: { scale: number; ring: number; glow: boolean };
  /** Host-set `selected` — an outline of this width, this far past the ring. */
  selected: { ring: number; offset: number };
  /** The producers count circle riding the dot — `ink` (solid, card text) or
   *  `soft` (the original SystemSketch pill's muted chip). */
  producers: { diameter: number; fontPx: number; style: "ink" | "soft" };
}

/* ------------------------------------------------------------------ */
/* The five                                                            */
/* ------------------------------------------------------------------ */

export const PORT_VARIANTS: Record<PortVariantId, PortVariant> = {
  // The DEFAULT. React Flow's 6px handle box (style.css:250-251) with a 1px
  // card gap and a 1.5px state ring: 11px painted beside 12px text — the
  // same ~0.9 dot:text ratio the DOM render Zach called "desired" (`115249`)
  // has at 24px, one rung down. Hollow; the ring is the state colour; wired
  // lights a centre. Nothing about the grammar changed — only the scale.
  v1: {
    id: "v1",
    title: "Fine ring",
    basedOn: "React Flow's 6px handle scale (xyflow style.css:250) in this trunk's own state-coloured three-circle grammar",
    dot: { diameter: PORT_DIAMETERS.xs, gap: 1, ring: 1.5, fill: "hollow", grammar: "trunk" },
    text: "xs",
    label: { weight: 400, font: "sans" },
    type: { size: "xs", opacity: 0.55 },
    hover: { scale: 1.35, ring: 3, glow: false },
    selected: { ring: 2, offset: 2 },
    producers: { diameter: 14, fontPx: 9, style: "ink" },
  },
  // The original SystemSketch port, by value, scaled with its text: an 8px
  // card disc, a 1px surface gap, a 1px ring in the TYPE's colour (12px
  // painted — the original's 18px footprint × 2/3); a default value fills it
  // muted, a cable fills it with the type colour. Monospace `name Type`
  // signature row; the count is the original's soft chip.
  v2: {
    id: "v2",
    title: "SystemSketch original",
    basedOn: "systemsketch block-canvas.css:1099-1132 (type ring, fills on wire) + portPalette.ts + the mono signature row, ×2/3",
    dot: { diameter: PORT_DIAMETERS.sm, gap: 1, ring: 1, fill: "typeOnWire", grammar: "systemsketch" },
    text: "xs",
    label: { weight: 400, font: "mono" },
    type: { size: "xs", opacity: 0.6 },
    hover: { scale: 1.25, ring: 3, glow: false },
    selected: { ring: 2, offset: 2 },
    producers: { diameter: 14, fontPx: 9, style: "soft" },
  },
  // langflow: a 10px disc FILLED with the type colour inside a 3px pale ring
  // of the same hue (16px painted), identical at rest whether or not a cable
  // is attached — langflow lets the cable say "wired". Hover glows.
  v3: {
    id: "v3",
    title: "Langflow",
    basedOn: "langflow handleRenderComponent/index.tsx:110-143 — 10px type-coloured disc, 3px pale ring, neon hover",
    dot: { diameter: 10, gap: 0, ring: 3, fill: "type", grammar: "langflow" },
    text: "xs",
    label: { weight: 500, font: "sans" },
    type: { size: "xs", opacity: 0.5 },
    hover: { scale: 1.15, ring: 0, glow: true },
    selected: { ring: 2, offset: 2 },
    producers: { diameter: 14, fontPx: 9, style: "ink" },
  },
  // React Flow UI's BaseHandle: an 11px pearl — light fill, 1px light
  // border — that turns React Flow's stock ink (#1a192b → `--foreground`)
  // once connected. The quietest of the five: empty ports nearly disappear
  // into the card, wired ones are the only dark marks on the wall.
  v4: {
    id: "v4",
    title: "React Flow UI pearl",
    basedOn: "ui.reactflow.dev BaseHandle (11px, border-slate-300, bg-slate-100) + stock xyflow ink when wired",
    dot: { diameter: 9, gap: 0, ring: 1, fill: "pearl", grammar: "pearl" },
    text: "xs",
    label: { weight: 400, font: "sans" },
    type: { size: "xs", opacity: 0.5 },
    hover: { scale: 1.3, ring: 3, glow: false },
    selected: { ring: 2, offset: 2 },
    producers: { diameter: 14, fontPx: 9, style: "ink" },
  },
  // Reticle: DP - Port's three circles drawn literally — hairline outline,
  // card background, and a centre that is ALWAYS drawn (muted until
  // something attaches, lit when wired). The largest box of the five (14px
  // painted) but the lightest ink: a 1px ring.
  v5: {
    id: "v5",
    title: "Reticle",
    basedOn: "DP - Port.md 'three stacked circles — outline, background, centre', the centre always drawn",
    dot: { diameter: PORT_DIAMETERS.md, gap: 0, ring: 1, fill: "centre", grammar: "reticle" },
    text: "xs",
    label: { weight: 400, font: "sans" },
    type: { size: "xs", opacity: 0.55 },
    hover: { scale: 1.2, ring: 3, glow: false },
    selected: { ring: 2, offset: 2 },
    producers: { diameter: 14, fontPx: 9, style: "ink" },
  },
};

/** One line per variant for a picker (the `app-variant-switch` lane's
 *  dropdown and a Storybook toolbar read this, not the titles). */
export const PORT_VARIANT_LABELS: Record<PortVariantId, string> = {
  v1: "v1 · Fine ring (default)",
  v2: "v2 · SystemSketch original",
  v3: "v3 · Langflow",
  v4: "v4 · React Flow UI pearl",
  v5: "v5 · Reticle",
};

/* ------------------------------------------------------------------ */
/* Derived geometry                                                    */
/* ------------------------------------------------------------------ */

/** How far the painted rings reach past the dot's box on each side. */
export function portVariantRingOverhangPx(variant: PortVariant): number {
  return variant.dot.gap + variant.dot.ring;
}

/** The painted outer diameter, px — box + both rings on both sides. */
export function portVariantOuterPx(variant: PortVariant): number {
  return variant.dot.diameter + 2 * portVariantRingOverhangPx(variant);
}

/** The painted OUTER radius of a dot at the variant's OWN diameter, px —
 *  `portVariantOuterPx / 2`, for a host whose dots are never sized apart
 *  from their variant (the app's blocks), so it needs no DOM to know it. */
export function portVariantRingRadiusPx(variant: PortVariant): number {
  return portVariantOuterPx(variant) / 2;
}

/**
 * The painted OUTER radius of one rendered `[data-slot="port-dot"]`, px, in
 * the dot's own LAYOUT space — where a wire has to stop to touch it (Zach,
 * 2026-09-22: "make the trace end exactly at the port"; the pull-back is
 * `trace.tsx`'s `traceRingGapPx`).
 *
 * WHY read off the element and not off the table alone: a caller may size a
 * dot (`diameter="md"` on a function port, an exact number) independently of
 * its variant, and only the rendered box knows. The rings are `box-shadow`
 * layers entirely OUTSIDE that box, so the box alone would stop a wire one
 * ring short; the ring widths come from the variant the dot says it painted
 * (`data-bbox-port-variant`, stamped by `port.tsx` on every dot).
 *
 * WHY `offsetWidth` and not `getBoundingClientRect`: the hover rule scales
 * the dot with a CSS `transform` (portVariants.css), which a bounding rect
 * includes and layout width does not — a wire must not jump because the
 * pointer happens to be over its dot. It is also UNSCALED by any ancestor
 * transform, so a canvas host projects it exactly like its anchors.
 */
export function portDotRingRadiusPx(dot: Element): number {
  const raw = dot.getAttribute(PORT_VARIANT_ATTR);
  const variant = PORT_VARIANTS[isPortVariantId(raw) ? raw : readPortVariantId()];
  const box = dot instanceof HTMLElement ? dot.offsetWidth : variant.dot.diameter;
  return box / 2 + portVariantRingOverhangPx(variant);
}

/**
 * The two numbers `port.tsx` publishes for the sketch skin's boundary pass
 * (`data-bbox-ring-expand` / `data-bbox-ring-pen`) — the SAME arithmetic
 * `port.tsx` used with its fixed constants (`SURFACE*2 + STATE*3`, `STATE`),
 * now over the variant's own rings.
 */
export function portVariantRingExpansion(variant: PortVariant): { expand: number; pen: number } {
  return { expand: variant.dot.gap * 2 + variant.dot.ring * 3, pen: variant.dot.ring };
}

/**
 * Where the producers circle's CENTRE sits relative to the dot's centre,
 * px, for a badge riding the side away from the label (`side`). It sits
 * just outside the painted ring on a 55° ray up-and-outward, overlapping
 * the ring by 2px like a notification badge.
 *
 * WHY that ray: the cables it counts arrive HORIZONTALLY at the dot's
 * centre (one attach point, elbow routing ends on the wall's normal), so a
 * badge straight outward would sit on them and one straight up would crowd
 * the port above; 55° up-outward clears both, and the original SystemSketch
 * pill made the same call ("Float over the incoming wire instead of
 * covering it", `block-canvas.css:1455-1457`). WHY overlap rather than
 * float free: a count that does not touch its dot reads as a label for the
 * row, not a fact about this port.
 */
export function portProducersOffsetPx(variant: PortVariant, side: "left" | "right"): { dx: number; dy: number } {
  const ringRadius = variant.dot.diameter / 2 + portVariantRingOverhangPx(variant);
  const reach = ringRadius + variant.producers.diameter / 2 - 2;
  const angle = (55 * Math.PI) / 180;
  const dx = Math.cos(angle) * reach;
  return { dx: side === "left" ? -dx : dx, dy: -Math.sin(angle) * reach };
}

/* ------------------------------------------------------------------ */
/* Type colour — only the two by-type grammars read it                 */
/* ------------------------------------------------------------------ */

/** A type's two paints: the full-strength `disc` and a pale `tint` of it. */
export interface PortTypePaint {
  disc: string;
  tint: string;
}

/**
 * The ORIGINAL SystemSketch palette by value (`systemsketch/src/blocks/ui/
 * portPalette.ts:23-40`, `portColorFamily` + `FAMILY_HEX`). Unknown types
 * are the original's own `any` amber — which is why the old boards read
 * orange.
 */
export function systemSketchTypeColor(type: string | undefined): string {
  const normalized = (type ?? "").trim().toLowerCase();
  if (normalized === "image") return "#c060e0";
  if (normalized === "text" || normalized === "str" || normalized === "string") return "#4caf50";
  if (normalized === "model") return "#2196f3";
  if (normalized === "number" || normalized === "int" || normalized === "float") return "#9e9e9e";
  if (normalized === "latent") return "#ff9800";
  return "#c08520";
}

/** langflow's light-theme `--datatype-*` pairs, `src/frontend/src/style/
 *  index.css:162-202`, transcribed (HSL components → `hsl()`). */
const LANGFLOW_DATATYPES = {
  pink: ["333.3 71.4% 50.6%", "325.7 77.8% 94.7%"],
  rose: ["346.8 77.2% 49.8%", "355.6 100% 94.7%"],
  yellow: ["40.6 96.1% 40.4%", "54.9 96.7% 88%"],
  blue: ["221.2 83.2% 53.3%", "214.3 94.6% 92.7%"],
  gray: ["215 13.8% 34.1%", "220 14.3% 95.9%"],
  lime: ["84.8 85.2% 34.5%", "79.6 89.1% 89.2%"],
  red: ["0 72.2% 50.6%", "0 93.3% 94.1%"],
  violet: ["262.1 83.3% 57.8%", "251.4 91.3% 95.5%"],
  emerald: ["161.4 93.5% 30.4%", "149.3 80.4% 90%"],
  fuchsia: ["293.4 69.5% 48.8%", "287 100% 95.5%"],
  purple: ["271.5 81.3% 55.9%", "268.7 100% 95.5%"],
  cyan: ["191.6 91.4% 36.5%", "185.1 95.9% 90.4%"],
  indigo: ["243.4 75.4% 58.6%", "226.5 100% 93.9%"],
  orange: ["20.5 90.2% 48.2%", "34.3 100% 91.8%"],
} as const satisfies Record<string, readonly [string, string]>;
type LangflowColor = keyof typeof LANGFLOW_DATATYPES;

/** The subset of langflow's `nodeColorsName` (`src/frontend/src/utils/
 *  styleUtils.ts:171-215`) whose colour has a `--datatype-*` pair above. */
const LANGFLOW_TYPE_COLORS: Record<string, LangflowColor> = {
  str: "indigo",
  Text: "indigo",
  Message: "indigo",
  number: "purple",
  Data: "red",
  JSON: "red",
  Document: "lime",
  Prompt: "violet",
  Embeddings: "emerald",
  BaseLanguageModel: "fuchsia",
  unknown: "gray",
};

/**
 * WHY a hash for names langflow never heard of — ours, not langflow's:
 * langflow paints every unmapped type gray (`get-node-output-colors-name.
 * ts:12`, `nodeColorsName[type] ?? nodeColorsName.unknown`), so a robotics
 * board (Pose, Twist, bool…) would render all-gray and the proposal's whole
 * point — colour BY type — would be invisible. Python's primitive names are
 * mapped onto langflow's own keys first (`int`/`float` → its `number`); the
 * rest hash stably into langflow's own palette, gray excluded.
 */
const LANGFLOW_HASH_PALETTE: LangflowColor[] = ["blue", "emerald", "orange", "pink", "cyan", "violet", "lime", "rose", "fuchsia", "yellow"];

export function langflowTypePaint(type: string | undefined): PortTypePaint {
  const raw = (type ?? "").trim();
  const lower = raw.toLowerCase();
  let color: LangflowColor | undefined = LANGFLOW_TYPE_COLORS[raw];
  if (!color && (lower === "int" || lower === "float" || lower === "number")) color = "purple";
  if (!color && (lower === "str" || lower === "string" || lower === "text")) color = "indigo";
  if (!color && raw === "") color = "gray";
  if (!color) {
    let hash = 0;
    for (const ch of raw) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
    color = LANGFLOW_HASH_PALETTE[hash % LANGFLOW_HASH_PALETTE.length];
  }
  const [disc, tint] = LANGFLOW_DATATYPES[color];
  return { disc: `hsl(${disc})`, tint: `hsl(${tint})` };
}

/**
 * The type paint a grammar uses, or `null` for the state-coloured ones. An
 * explicit `typeColor` (a host that knows better) wins; its tint is that
 * colour washed into the card, the same relation langflow's pairs have.
 */
export function portTypePaint(grammar: PortGrammar, dataType: string | undefined, typeColor: string | undefined): PortTypePaint | null {
  if (grammar !== "systemsketch" && grammar !== "langflow") return null;
  if (typeColor) return { disc: typeColor, tint: `color-mix(in srgb, ${typeColor} 18%, var(--card))` };
  if (grammar === "langflow") return langflowTypePaint(dataType);
  const disc = systemSketchTypeColor(dataType);
  return { disc, tint: `color-mix(in srgb, ${disc} 18%, var(--card))` };
}

/* ------------------------------------------------------------------ */
/* CSS custom properties — what a port root publishes inline           */
/* ------------------------------------------------------------------ */

/**
 * The property set, spelled once. `portVariants.css` declares the same
 * names per `[data-bbox-port-variant]`; the inline copy on each port root
 * is what makes a port self-sufficient for a consumer who never imports
 * that stylesheet (shadcn copies component source, not our globals).
 */
export function portVariantVars(variant: PortVariant): CSSProperties {
  return {
    "--bbox-port-dot-diameter": `${variant.dot.diameter}px`,
    "--bbox-port-dot-gap": `${variant.dot.gap}px`,
    "--bbox-port-dot-ring": `${variant.dot.ring}px`,
    "--bbox-port-ring-overhang": `${portVariantRingOverhangPx(variant)}px`,
    "--bbox-port-label-size": `${PORT_TEXT_SIZES[variant.text]}px`,
    "--bbox-port-label-weight": String(variant.label.weight),
    "--bbox-port-type-size": `${PORT_TEXT_SIZES[variant.type.size]}px`,
    "--bbox-port-type-opacity": String(variant.type.opacity),
    "--bbox-port-hover-scale": String(variant.hover.scale),
    "--bbox-port-hover-ring": `${variant.hover.ring}px`,
    "--bbox-port-selected-ring": `${variant.selected.ring}px`,
    "--bbox-port-selected-offset": `${variant.selected.offset}px`,
    "--bbox-port-producers-size": `${variant.producers.diameter}px`,
    "--bbox-port-producers-font": `${variant.producers.fontPx}px`,
  } as CSSProperties;
}

/** The label's font stack for a variant — through the skin's own tokens so
 *  the sketch skin still re-fonts every variant. */
export function portVariantLabelFont(variant: PortVariant): string {
  return variant.label.font === "mono"
    ? 'var(--bbox-skin-font-mono, ui-monospace, "SF Mono", Menlo, Consolas, monospace)'
    : "var(--bbox-skin-font-sans, inherit)";
}

/* ------------------------------------------------------------------ */
/* Resolution — the attribute, read live                               */
/* ------------------------------------------------------------------ */

export function isPortVariantId(value: unknown): value is PortVariantId {
  return typeof value === "string" && (PORT_VARIANT_IDS as readonly string[]).includes(value);
}

/**
 * The variant in force for the whole document: `<html data-bbox-port-
 * variant>`, or `v1`. An unknown value is NOT an error — it resolves to the
 * default, so a stale attribute from an older build can never blank every
 * port on the board. Safe under SSR (`layering.test.ts` renders `Port`
 * with `renderToStaticMarkup`): no `document`, no attribute, `v1`.
 */
export function readPortVariantId(): PortVariantId {
  if (typeof document === "undefined") return DEFAULT_PORT_VARIANT_ID;
  const raw = document.documentElement.dataset.bboxPortVariant;
  return isPortVariantId(raw) ? raw : DEFAULT_PORT_VARIANT_ID;
}

const listeners = new Set<() => void>();
let observer: MutationObserver | null = null;

/** One shared observer on `<html>`'s attribute, alive only while a port is
 *  mounted — every mounted port shares it rather than each owning one. */
function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  if (observer == null && typeof MutationObserver !== "undefined" && typeof document !== "undefined") {
    observer = new MutationObserver(() => {
      for (const l of listeners) l();
    });
    observer.observe(document.documentElement, { attributes: true, attributeFilter: [PORT_VARIANT_ATTR] });
  }
  return () => {
    listeners.delete(listener);
    if (listeners.size === 0 && observer != null) {
      observer.disconnect();
      observer = null;
    }
  };
}

/**
 * The same `<html>` attribute subscription `usePortVariant` rides, for a
 * NON-React reader that caches geometry off the variant (a canvas engine's
 * reactive store, `WireLayer`'s measurement). Returns the unsubscribe.
 */
export function subscribePortVariant(listener: () => void): () => void {
  return subscribe(listener);
}

function serverSnapshot(): PortVariantId {
  return DEFAULT_PORT_VARIANT_ID;
}

/**
 * The variant this port renders: an explicit `override` (a gallery showing
 * all five at once, a host pinning one subtree) wins; otherwise the
 * document-wide attribute, subscribed so a switch re-renders every mounted
 * port without a remount.
 */
export function usePortVariant(override?: PortVariantId): PortVariant {
  const documentId = useSyncExternalStore(subscribe, readPortVariantId, serverSnapshot);
  return PORT_VARIANTS[override ?? documentId];
}
